def audit_gap_register(output: Path) -> dict[str, Any]:
    output = output.resolve()
    root = _root(output)
    if not root.is_dir():
        return {"schema_version": GAP_SCHEMA_VERSION, "status": "passed", "initialized": False, "counts": {"total": 0, "open": 0, "deferred": 0, "resolved": 0}, "errors": []}
    errors: list[str] = []
    records = gap_records(output)
    for path in sorted(_records_root(output).glob("gap-*.json")):
        item = json_load(path)
        if not isinstance(item, dict):
            errors.append(f"{path.name}: gap record must be an object")
            continue
        errors.extend(_record_errors(output, path, item))
    index_path = root / "index.json"
    index = json_load(index_path) if index_path.is_file() else {}
    if not index_path.is_file():
        errors.append("gap index is missing")
    expected = _index_value(records)
    for key in ("schema_version", "status", "counts", "counts_by_kind", "gaps"):
        if index.get(key) != expected.get(key):
            errors.append(f"gap index mismatch: {key}")
    if (output / "human/gaps").exists() or (output / "markdown/gaps").exists():
        errors.append("research gaps must not create one human page per gap")
    for human_root in (output / "human", output / "markdown"):
        if human_root.is_dir():
            records_page = human_root / "RECORDS.md"
            text = records_page.read_text(encoding="utf-8-sig") if records_page.is_file() else ""
            if text.count("## 研究缺口与待补来源") != 1:
                errors.append(f"single research-gap navigation entry is missing: {records_page}")
    database = output / "machine/knowledge.sqlite"
    if database.is_file():
        import sqlite3
        with sqlite3.connect(database) as connection:
            tables = {row[0] for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table'")}
            if "research_gaps" not in tables:
                errors.append("machine knowledge research_gaps table is missing")
            elif connection.execute("SELECT count(*) FROM research_gaps").fetchone()[0] != len(records):
                errors.append("machine gap count mismatch")
    counts = Counter(str(item.get("status")) for item in records)
    return {"schema_version": GAP_SCHEMA_VERSION, "status": "passed" if not errors else "failed", "initialized": True, "counts": {"total": len(records), **{name: counts.get(name, 0) for name in GAP_STATUSES}}, "index": str(index_path.resolve()), "errors": errors}

"""Audited, reversible extension of a completed CKB knowledge scope."""

from __future__ import annotations

import hashlib
import json
import gc
from pathlib import Path, PurePosixPath
import shutil
import sqlite3
from typing import Any
import warnings

from .common import CkbError, json_load, json_write, path_inside, sha256_file, stable_id
from .gitrepo import LANGUAGE_BY_SUFFIX, preflight
from .migration import (
    _entity_key,
    _preserve_mutable_layers,
    _replace_review_packs,
    _review_for_new_entity,
    _review_shape,
    _selected_entities,
)
from .pipeline import build_chunk, finalize, initialize, status as pipeline_status


SCOPE_EXTENSION_SCHEMA_VERSION = 1
STATE_RELATIVE = Path("scope-extension/state.json")
PLAN_RELATIVE = Path("scope-extension/plan.json")
AUDIT_RELATIVE = Path("scope-extension/audit.json")
SUPPORTED_LANGUAGES = tuple(sorted(set(LANGUAGE_BY_SUFFIX.values())))


def _error(category: str, message: str) -> CkbError:
    return CkbError(f"scope-extension:{category}: {message}")


def _canonical_entry(value: str) -> str:
    value = value.strip()
    if "#" not in value:
        raise _error("entry-shape", f"new entry must use LANGUAGE:PATH#QUALIFIED_NAME: {value}")
    left, qualified = value.split("#", 1)
    if ":" not in left:
        raise _error("entry-shape", f"new entry must use LANGUAGE:PATH#QUALIFIED_NAME: {value}")
    language, path = left.split(":", 1)
    language = language.strip().casefold()
    normalized_path = PurePosixPath(path.replace("\\", "/").strip("/"))
    if language not in SUPPORTED_LANGUAGES:
        raise _error("unsupported-language", f"entry language is not supported: {language}")
    if not path or normalized_path.is_absolute() or ".." in normalized_path.parts:
        raise _error("entry-path", f"entry path must be a repository-relative source path: {path}")
    if not qualified.strip():
        raise _error("entry-qualified-name", "entry qualified name must not be empty")
    return f"{language}:{normalized_path.as_posix()}#{qualified.strip()}"


def _tree_manifest(root: Path) -> dict[str, Any]:
    root = root.resolve()
    if not root.is_dir():
        raise _error("output-missing", f"directory does not exist: {root}")
    files: list[dict[str, Any]] = []
    for path in sorted((item for item in root.rglob("*") if item.is_file()), key=lambda item: item.relative_to(root).as_posix()):
        relative = path.relative_to(root).as_posix()
        files.append({"path": relative, "size": path.stat().st_size, "sha256": sha256_file(path)})
    canonical = json.dumps(files, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return {
        "algorithm": "sha256-tree-v1",
        "file_count": len(files),
        "byte_count": sum(int(item["size"]) for item in files),
        "sha256": hashlib.sha256(canonical).hexdigest(),
        "files": files,
    }


def _same_manifest(left: dict[str, Any], right: dict[str, Any]) -> bool:
    return all(left.get(key) == right.get(key) for key in ("algorithm", "file_count", "byte_count", "sha256", "files"))


def _sqlite_checks(output: Path) -> list[dict[str, Any]]:
    checks: list[dict[str, Any]] = []
    for relative in ("machine/knowledge.sqlite", "agent-index.sqlite", "machine/automation.sqlite"):
        path = output / relative
        if not path.is_file():
            if relative == "machine/automation.sqlite":
                continue
            checks.append({"path": relative, "integrity_check": "missing", "foreign_key_errors": None, "passed": False})
            continue
        connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
        try:
            integrity = str(connection.execute("PRAGMA integrity_check").fetchone()[0])
            foreign_keys = connection.execute("PRAGMA foreign_key_check").fetchall()
        finally:
            connection.close()
        checks.append({
            "path": relative,
            "integrity_check": integrity,
            "foreign_key_errors": [list(row) for row in foreign_keys],
            "passed": integrity == "ok" and not foreign_keys,
        })
    return checks


def _release_audit_handles() -> None:
    """Release transient sqlite objects left by read-only audit helpers."""
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", ResourceWarning)
        gc.collect()


def _candidate_graph(output: Path) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    state = json_load(output / "state.json")
    entities: dict[str, dict[str, Any]] = {}
    links: dict[str, dict[str, Any]] = {}
    for batch in state["parse_batches"]:
        candidate = json_load(output / "chunks" / batch["id"] / "candidate.json")
        entities.update((item["id"], item) for item in candidate.get("entities", []))
        links.update((item["id"], item) for item in candidate.get("links", []))
    return [entities[key] for key in sorted(entities)], [links[key] for key in sorted(links)]


def _dimension(old_values: set[str], new_values: set[str]) -> dict[str, Any]:
    return {
        "retained": sorted(old_values & new_values),
        "added": sorted(new_values - old_values),
        "removed": sorted(old_values - new_values),
        "counts": {
            "retained": len(old_values & new_values),
            "added": len(new_values - old_values),
            "removed": len(old_values - new_values),
        },
    }


def _page_ids(document: dict[str, Any]) -> set[str]:
    return set(document.get("page_entity_ids") or [])


def _replace_prefix(value: Any, old: str, new: str) -> Any:
    if isinstance(value, dict):
        return {key: _replace_prefix(item, old, new) for key, item in value.items()}
    if isinstance(value, list):
        return [_replace_prefix(item, old, new) for item in value]
    if isinstance(value, str):
        return value.replace(old, new).replace(old.replace("\\", "/"), new.replace("\\", "/"))
    return value


def _rebind_preserved_json(staging: Path, previous_output: Path, mutable_files: list[dict[str, Any]]) -> list[str]:
    changed: list[str] = []
    old = str(previous_output.resolve())
    new = str(staging.resolve())
    for item in mutable_files:
        relative = str(item.get("relative_target") or "")
        path = staging / relative
        if path.suffix.casefold() != ".json" or not path.is_file():
            continue
        try:
            value = json_load(path)
        except (CkbError, OSError, UnicodeError, json.JSONDecodeError):
            continue
        updated = _replace_prefix(value, old, new)
        if updated != value:
            json_write(path, updated)
            changed.append(relative)
        item["post_extension_sha256"] = sha256_file(path)
        item["post_extension_size"] = path.stat().st_size
    return sorted(changed)


def _layer_inventory(output: Path, mutable_files: list[dict[str, Any]] | None = None) -> dict[str, Any]:
    gaps = list((output / "workspace-meta/gaps/records").glob("gap-*.json"))
    gap_statuses: dict[str, int] = {}
    for path in gaps:
        status = str(json_load(path).get("status"))
        gap_statuses[status] = gap_statuses.get(status, 0) + 1
    manifests = list((output / "references/manifests").glob("*.json"))
    reference_statuses: dict[str, int] = {}
    for path in manifests:
        status = str(json_load(path).get("status"))
        reference_statuses[status] = reference_statuses.get(status, 0) + 1
    records = mutable_files or []
    return {
        "work_record_count": len(list((output / "workspace-meta/notes").glob("*.json"))),
        "reference_count": len(manifests),
        "reference_statuses": dict(sorted(reference_statuses.items())),
        "gap_count": len(gaps),
        "gap_statuses": dict(sorted(gap_statuses.items())),
        "feedback_count": len(list((output / "workspace-meta/feedback").glob("*/*.json"))),
        "operation_shard_count": len(list((output / "workspace-meta/operations").glob("*.jsonl"))),
        "vault_user_files": sorted(
            item["relative_target"]
            for item in records
            if item.get("kind") == "vault-user-file"
        ),
    }


def _preservation_errors(staging: Path, records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    errors: list[dict[str, Any]] = []
    for item in records:
        relative = str(item.get("relative_target") or "")
        baseline_relative = str(item.get("baseline_relative_target") or "")
        target = staging / relative
        baseline = staging / baseline_relative
        if not baseline.is_file() or sha256_file(baseline) != item.get("baseline_sha256"):
            errors.append({"path": relative, "reason": "baseline-missing-or-changed"})
            continue
        if not target.is_file():
            errors.append({"path": relative, "reason": "live-file-missing"})
            continue
        # A same-snapshot scope extension does not rekey page titles.  Vault
        # user bytes, including learning notes and work-record prose, therefore
        # remain exact; JSON control records may receive bounded path rebinding.
        if item.get("kind") == "vault-user-file" and sha256_file(target) != item.get("initial_target_sha256"):
            errors.append({"path": relative, "reason": "vault-user-file-changed"})
    return errors


def _recomputed_review_sets(staging: Path, old_graph: dict[str, Any]) -> tuple[set[str], set[str], set[str]]:
    new_entities, _sources = _selected_entities(staging)
    _candidate_entities, candidate_links = _candidate_graph(staging)
    old_links = {item["id"]: item for item in old_graph.get("links", [])}
    new_links = {item["id"]: item for item in candidate_links}
    added_relation_ids = set(new_links) - set(old_links)
    affected_ids = {
        endpoint
        for relation_id in added_relation_ids
        for endpoint in (new_links[relation_id].get("source"), new_links[relation_id].get("target"))
        if endpoint
    }
    catalog = json_load(staging / "catalog.json")
    reuse_paths = set((catalog.get("migration_reuse") or {}).get("reused_file_paths", []))
    old_by_key = {_entity_key(entity): entity for entity in old_graph.get("entities", [])}
    reusable: set[str] = set()
    for entity in new_entities:
        previous = old_by_key.get(_entity_key(entity))
        if (
            entity["path"] in reuse_paths
            and entity["id"] not in affected_ids
            and previous
            and previous.get("review_status") == "agent-reviewed"
            and _review_shape(previous.get("classification")) == _review_shape(entity.get("classification"))
        ):
            reusable.add(entity["id"])
    selected = {item["id"] for item in new_entities}
    return reusable, selected - reusable, added_relation_ids


def _load_extension_state(output: Path) -> dict[str, Any]:
    path = output.resolve() / STATE_RELATIVE
    if not path.is_file():
        raise _error("state-missing", f"scope extension state does not exist: {path}")
    value = json_load(path)
    if value.get("schema_version") != SCOPE_EXTENSION_SCHEMA_VERSION:
        raise _error("state-schema", "scope extension state schema is unsupported")
    if Path(str(value.get("staging_output"))).resolve() != output.resolve():
        raise _error("absolute-binding", "state staging_output does not match the requested output")
    return value


def start_scope_extension(
    previous_output: Path,
    repository: Path,
    staging: Path,
    entries: list[str],
    expand_depth: int,
    expand_direction: str,
) -> dict[str, Any]:
    previous_output = previous_output.resolve()
    repository = repository.resolve()
    staging = staging.resolve()
    if path_inside(staging, previous_output) or path_inside(previous_output, staging):
        raise _error("overlapping-output", "staging and previous OUTPUT must be separate, non-overlapping directories")
    if expand_depth < 0:
        raise _error("expand-depth", "extension depth must be zero or greater")
    if expand_direction not in {"both", "callers", "callees"}:
        raise _error("expand-direction", f"unsupported expansion direction: {expand_direction}")
    canonical_added = [_canonical_entry(value) for value in entries]
    if not canonical_added:
        raise _error("entry-required", "at least one new entry is required")
    if len(set(canonical_added)) != len(canonical_added):
        raise _error("duplicate-entry", "the same new center was supplied more than once")

    old_state = json_load(previous_output / "state.json")
    old_audit = json_load(previous_output / "audit/global.json")
    old_scope = json_load(previous_output / "scope.json")
    old_graph = json_load(previous_output / "graph.json")
    if old_state.get("status") != "complete" or old_audit.get("status") != "passed" or not (previous_output / ".complete").is_file():
        raise _error("origin-not-audited", f"previous OUTPUT is not complete and globally audited: {previous_output}")
    selectors = old_scope.get("selectors") or {}
    old_entries = list(selectors.get("entries") or [])
    old_canonical = {_canonical_entry(value) for value in old_entries if "#" in str(value)}
    duplicates = sorted(set(canonical_added) & old_canonical)
    if duplicates:
        raise _error("entry-already-present", f"new center already exists in the old scope: {duplicates}")
    target_entries = [*old_entries, *sorted(canonical_added)]
    repository_state = preflight(repository)
    operation_id = stable_id(
        "scope-extension",
        previous_output,
        repository_state["commit"],
        *target_entries,
        expand_depth,
        expand_direction,
    )
    request = {
        "previous_output": str(previous_output),
        "repository": str(repository),
        "repository_commit": repository_state["commit"],
        "staging_output": str(staging),
        "added_entries": sorted(canonical_added),
        "target_entries": target_entries,
        "expand_depth": expand_depth,
        "expand_direction": expand_direction,
    }
    if staging.exists():
        state_path = staging / STATE_RELATIVE
        if not state_path.is_file():
            raise _error("staging-not-empty", f"staging already exists without matching extension state: {staging}")
        existing = _load_extension_state(staging)
        if existing.get("operation_id") != operation_id or existing.get("request") != request:
            raise _error("staging-conflict", "staging is bound to a different scope extension request")
        return extension_status(staging)

    origin_manifest = _tree_manifest(previous_output)
    try:
        initialize(
            repository,
            staging,
            old_state["format"],
            list(selectors.get("scope_paths") or []),
            target_entries,
            expand_depth,
            expand_direction,
            list(selectors.get("include") or []),
            csharp_solution=selectors.get("csharp_solution"),
            csharp_project=selectors.get("csharp_project"),
            allow_dotnet_restore=bool(selectors.get("allow_dotnet_restore", False)),
            page_config_path=previous_output / "page-config.json",
            reuse_from_output=previous_output,
        )
        mutable_files = _preserve_mutable_layers(previous_output, staging)
        rebound_json = _rebind_preserved_json(staging, previous_output, mutable_files)
        state = json_load(staging / "state.json")
        for batch in state["parse_batches"]:
            build_chunk(staging, batch["id"], "all")
        new_entities, _sources = _selected_entities(staging)
        _candidate_entities, candidate_links = _candidate_graph(staging)
        old_links = {item["id"]: item for item in old_graph.get("links", [])}
        new_links = {item["id"]: item for item in candidate_links}
        added_relation_ids = set(new_links) - set(old_links)
        affected_ids = {
            endpoint
            for relation_id in added_relation_ids
            for endpoint in (new_links[relation_id].get("source"), new_links[relation_id].get("target"))
            if endpoint
        }
        catalog = json_load(staging / "catalog.json")
        reuse_paths = set((catalog.get("migration_reuse") or {}).get("reused_file_paths", []))
        old_by_key = {_entity_key(entity): entity for entity in old_graph.get("entities", [])}
        reusable_reviews: dict[str, dict[str, Any]] = {}
        id_map: dict[str, str] = {}
        for entity in new_entities:
            previous = old_by_key.get(_entity_key(entity))
            if (
                entity["path"] in reuse_paths
                and entity["id"] not in affected_ids
                and previous
                and previous.get("review_status") == "agent-reviewed"
                and _review_shape(previous.get("classification")) == _review_shape(entity.get("classification"))
            ):
                reusable_reviews[entity["id"]] = _review_for_new_entity(entity, previous)
                id_map[str(previous["id"])] = entity["id"]
        reused_ids, delta_ids = _replace_review_packs(staging, reusable_reviews)

        new_scope = json_load(staging / "scope.json")
        new_navigation = json_load(staging / "navigation-plan.json")
        old_navigation = old_graph.get("navigation_plan") or {}
        dimensions = {
            "entries": _dimension(set(old_entries), set(target_entries)),
            "paths": _dimension(set(old_scope.get("selected_file_paths") or []), set(new_scope.get("selected_file_paths") or [])),
            "entities": _dimension({item["id"] for item in old_graph.get("entities", [])}, set(new_scope.get("selected_entity_ids") or [])),
            "relations": _dimension(set(old_links), set(new_links)),
            "pages": _dimension(_page_ids(old_navigation), _page_ids(new_navigation)),
        }
        removed = {name: value["removed"] for name, value in dimensions.items() if value["removed"]}
        if removed:
            raise _error("scope-contraction", f"append-only extension removed prior scope items: {removed}")
        final_state = json_load(staging / "state.json")
        extension = {
            "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
            "operation_id": operation_id,
            "status": "pending-agent-review" if delta_ids else "ready-for-audit",
            "previous_output": str(previous_output),
            "staging_output": str(staging),
            "repository": str(repository),
            "repository_commit": repository_state["commit"],
            "request": request,
        }
        final_state["scope_extension"] = extension
        json_write(staging / "state.json", final_state)
        plan = {
            "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
            "operation_id": operation_id,
            "status": extension["status"],
            "bindings": {
                "previous_output": str(previous_output),
                "staging_output": str(staging),
                "repository": str(repository),
                "repository_commit": repository_state["commit"],
                "origin_commit": old_state.get("repository", {}).get("commit"),
            },
            "selectors": {
                "old_entries": old_entries,
                "added_entries": sorted(canonical_added),
                "target_entries": target_entries,
                "expand_depth": expand_depth,
                "expand_direction": expand_direction,
            },
            "delta": dimensions,
            "review": {
                "reused_entity_ids": sorted(reused_ids),
                "delta_entity_ids": sorted(delta_ids),
                "affected_relation_ids": sorted(added_relation_ids),
                "affected_existing_entity_ids": sorted(affected_ids & {item["id"] for item in old_graph.get("entities", [])}),
                "old_to_new_id_map": id_map,
            },
            "reuse": {
                "file_paths": sorted(reuse_paths),
                "file_count": len(reuse_paths),
                "review_entity_count": len(reused_ids),
                "delta_review_entity_count": len(delta_ids),
            },
            "preservation": {
                "origin_manifest": origin_manifest,
                "mutable_files": mutable_files,
                "rebound_json_files": rebound_json,
                "origin_layers": _layer_inventory(previous_output, mutable_files),
            },
        }
        json_write(staging / PLAN_RELATIVE, plan)
        json_write(staging / STATE_RELATIVE, {**extension, "request": request})
    except Exception as exc:
        if staging.exists():
            shutil.rmtree(staging)
        if isinstance(exc, CkbError) and str(exc).startswith("scope-extension:"):
            raise
        message = str(exc)
        category = "entry-resolution" if "entry resolves to" in message else "start-failed"
        raise _error(category, message) from exc
    return extension_status(staging)


def _control_records(output: Path) -> list[tuple[Path, dict[str, Any]]]:
    """Load and validate the immutable control history for one OUTPUT name.

    Legacy schema-1 records did not persist parent_operation_id.  Their parent
    is inferred only when exactly one older modified manifest equals the
    child's origin manifest.  New records persist that same relation and depth.
    """
    output = output.resolve()
    records: list[tuple[Path, dict[str, Any]]] = []
    by_id: dict[str, tuple[Path, dict[str, Any]]] = {}
    for path in sorted(output.parent.glob(f".{output.name}.scope-extension-*.json")):
        value = json_load(path)
        operation_id = str(value.get("operation_id") or "")
        if value.get("schema_version") != SCOPE_EXTENSION_SCHEMA_VERSION or not operation_id:
            raise _error("control-record-drift", f"control record schema or operation id is invalid: {path}")
        if path != _control_path(output, operation_id):
            raise _error("control-record-drift", f"control record path does not match operation id: {path}")
        if Path(str(value.get("output") or "")).resolve() != output:
            raise _error("control-record-drift", f"control record OUTPUT binding drifted: {path}")
        if operation_id in by_id:
            raise _error("control-record-drift", f"duplicate control operation id: {operation_id}")
        item = json.loads(json.dumps(value))
        records.append((path, item))
        by_id[operation_id] = (path, item)

    for path, value in records:
        origin = value.get("origin_manifest")
        if not isinstance(origin, dict):
            raise _error("control-record-drift", f"control origin manifest is missing: {path}")
        inferred = [
            candidate
            for _candidate_path, candidate in records
            if candidate.get("operation_id") != value.get("operation_id")
            and isinstance(candidate.get("modified_manifest"), dict)
            and _same_manifest(candidate["modified_manifest"], origin)
        ]
        if "parent_operation_id" in value:
            parent_id = value.get("parent_operation_id")
            if parent_id is not None:
                parent = by_id.get(str(parent_id))
                if parent is None or not isinstance(parent[1].get("modified_manifest"), dict) or not _same_manifest(parent[1]["modified_manifest"], origin):
                    raise _error("control-record-drift", f"parent operation does not produce the child origin: {path}")
        else:
            if len(inferred) > 1:
                raise _error("control-record-drift", f"legacy parent operation is ambiguous: {path}")
            parent_id = inferred[0]["operation_id"] if inferred else None
        value["parent_operation_id"] = parent_id

    depths: dict[str, int] = {}

    def depth(operation_id: str, trail: set[str]) -> int:
        if operation_id in depths:
            return depths[operation_id]
        if operation_id in trail:
            raise _error("control-record-drift", f"control parent cycle includes: {operation_id}")
        value = by_id[operation_id][1]
        parent_id = value.get("parent_operation_id")
        result = 1 if parent_id is None else depth(str(parent_id), {*trail, operation_id}) + 1
        recorded = value.get("chain_depth")
        if recorded is not None and int(recorded) != result:
            raise _error("control-record-drift", f"control chain depth drifted: {operation_id}")
        value["chain_depth"] = result
        depths[operation_id] = result
        return result

    for _path, value in records:
        depth(str(value["operation_id"]), set())
    return records


def _control_selection(output: Path, actual_manifest: dict[str, Any] | None = None) -> dict[str, Any]:
    output = output.resolve()
    records = _control_records(output)
    actual = actual_manifest or _tree_manifest(output)
    active = [
        (path, value)
        for path, value in records
        if value.get("status") == "cutover-complete"
        and isinstance(value.get("modified_manifest"), dict)
        and _same_manifest(value["modified_manifest"], actual)
    ]
    if len(active) > 1:
        raise _error("control-record-active-ambiguous", f"multiple active cutovers match current OUTPUT: {[item[1]['operation_id'] for item in active]}")
    rolled_back = [
        (path, value)
        for path, value in records
        if value.get("status") == "rolled-back"
        and _same_manifest(value["origin_manifest"], actual)
    ]
    return {
        "records": records,
        "actual_manifest": actual,
        "active": active[0] if active else None,
        "rolled_back_matches": rolled_back,
    }


def _public_control(value: dict[str, Any]) -> dict[str, Any]:
    return json.loads(json.dumps(value))


def extension_status(output: Path) -> dict[str, Any]:
    output = output.resolve()
    controls = sorted(output.parent.glob(f".{output.name}.scope-extension-*.json"))
    if controls:
        selection = _control_selection(output)
        if selection["active"]:
            _path, active = selection["active"]
            return {
                "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
                "status": "cutover-complete",
                "active_operation_id": active["operation_id"],
                "parent_operation_id": active.get("parent_operation_id"),
                "chain_depth": active["chain_depth"],
                "cutover": _public_control(active),
                "control_record_count": len(selection["records"]),
            }
        rolled_back = selection["rolled_back_matches"]
        return {
            "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
            "status": "rolled-back" if len(rolled_back) == 1 else "no-active-cutover",
            "active_operation_id": None,
            "rolled_back_operation_id": rolled_back[0][1]["operation_id"] if len(rolled_back) == 1 else None,
            "matching_rolled_back_operation_ids": [value["operation_id"] for _path, value in rolled_back],
            "control_record_count": len(selection["records"]),
        }
    state = _load_extension_state(output)
    plan = json_load(output / PLAN_RELATIVE)
    build_state = json_load(output / "state.json")
    pending = [item["id"] for item in build_state.get("review_packs", []) if item.get("status") != "passed"]
    return {
        "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
        "status": state["status"],
        "operation_id": state["operation_id"],
        "previous_output": state["previous_output"],
        "staging_output": state["staging_output"],
        "repository_commit": state["repository_commit"],
        "pending_review_packs": pending,
        "next_review_template": next((item.get("review_template_path") for item in build_state.get("review_packs", []) if item.get("status") != "passed"), None),
        "delta": plan["delta"],
        "reuse": plan["reuse"],
    }


def audit_scope_extension(staging: Path) -> dict[str, Any]:
    staging = staging.resolve()
    state = _load_extension_state(staging)
    plan = json_load(staging / PLAN_RELATIVE)
    checks: list[dict[str, Any]] = []

    def check(name: str, passed: bool, detail: Any, category: str) -> None:
        checks.append({"name": name, "passed": bool(passed), "category": category, "detail": detail})

    origin = Path(state["previous_output"])
    actual_origin = _tree_manifest(origin)
    expected_origin = plan["preservation"]["origin_manifest"]
    check("origin-output-unchanged", _same_manifest(actual_origin, expected_origin), {"expected": expected_origin["sha256"], "actual": actual_origin["sha256"]}, "origin-drift")
    repository_state = preflight(Path(state["repository"]))
    check("target-repository-pinned", repository_state["commit"] == state["repository_commit"], repository_state, "target-drift")
    removed = {name: value["removed"] for name, value in plan["delta"].items() if value["removed"]}
    check("append-only-delta", not removed, removed, "scope-contraction")
    build_state = json_load(staging / "state.json")
    old_graph = json_load(origin / "graph.json")
    expected_reused, expected_delta, expected_added_relations = _recomputed_review_sets(staging, old_graph)
    actual_reused = {
        entity_id
        for pack in build_state.get("review_packs", [])
        if str(pack.get("id", "")).startswith("migrated-")
        for entity_id in pack.get("entity_ids", [])
    }
    actual_delta = {
        entity_id
        for pack in build_state.get("review_packs", [])
        if str(pack.get("id", "")).startswith("delta-")
        for entity_id in pack.get("entity_ids", [])
    }
    review_detail = {
        "reused_missing": sorted(expected_reused - actual_reused),
        "reused_extra": sorted(actual_reused - expected_reused),
        "delta_missing": sorted(expected_delta - actual_delta),
        "delta_extra": sorted(actual_delta - expected_delta),
        "relation_delta_missing": sorted(expected_added_relations - set(plan["review"]["affected_relation_ids"])),
        "relation_delta_extra": sorted(set(plan["review"]["affected_relation_ids"]) - expected_added_relations),
        "plan_reused_missing": sorted(expected_reused - set(plan["review"]["reused_entity_ids"])),
        "plan_reused_extra": sorted(set(plan["review"]["reused_entity_ids"]) - expected_reused),
        "plan_delta_missing": sorted(expected_delta - set(plan["review"]["delta_entity_ids"])),
        "plan_delta_extra": sorted(set(plan["review"]["delta_entity_ids"]) - expected_delta),
    }
    check("exact-delta-review-set", not any(review_detail.values()), review_detail, "delta-review-drift")
    preservation_errors = _preservation_errors(staging, plan["preservation"]["mutable_files"])
    actual_layers = _layer_inventory(staging, plan["preservation"]["mutable_files"])
    expected_layers = plan["preservation"]["origin_layers"]
    check(
        "mutable-layers-preserved",
        not preservation_errors and actual_layers == expected_layers,
        {"errors": preservation_errors, "expected": expected_layers, "actual": actual_layers},
        "mutable-layer-loss",
    )
    pending = [item["id"] for item in build_state.get("review_packs", []) if item.get("status") != "passed"]
    check("delta-reviews-complete", not pending, pending, "review-pending")
    final_result: dict[str, Any] | None = None
    if not pending and all(item["passed"] for item in checks):
        try:
            final_result = finalize(staging)
        except CkbError as exc:
            check("global-finalize", False, str(exc), "global-audit")
        else:
            check("global-finalize", final_result.get("status") == "complete", final_result.get("global_audit"), "global-audit")
    else:
        check("global-finalize", False, "blocked by earlier extension checks", "blocked")
    global_audit = json_load(staging / "audit/global.json") if (staging / "audit/global.json").is_file() else {}
    check("global-audit-passed", global_audit.get("status") == "passed", global_audit.get("status"), "global-audit")
    sqlite_checks = _sqlite_checks(staging)
    check("sqlite-integrity-and-foreign-keys", bool(sqlite_checks) and all(item["passed"] for item in sqlite_checks), sqlite_checks, "sqlite-integrity")
    from .llm_wiki_capabilities import maintenance_check

    maintenance = maintenance_check(staging) if global_audit.get("status") == "passed" else {"status": "blocked"}
    _release_audit_handles()
    check("maintain", maintenance.get("status") == "passed", maintenance, "maintain")
    passed = all(item["passed"] for item in checks)
    result = {
        "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
        "operation_id": state["operation_id"],
        "status": "ready" if passed else "failed",
        "checks": checks,
        "counts": {"passed": sum(item["passed"] for item in checks), "total": len(checks)},
        "sqlite": sqlite_checks,
        "maintenance_status": maintenance.get("status"),
    }
    json_write(staging / AUDIT_RELATIVE, result)
    if passed:
        state["status"] = "ready"
        plan["status"] = "ready"
        json_write(staging / STATE_RELATIVE, state)
        json_write(staging / PLAN_RELATIVE, plan)
        build_state = json_load(staging / "state.json")
        build_state["scope_extension"] = {**build_state.get("scope_extension", {}), "status": "ready"}
        json_write(staging / "state.json", build_state)
    return result


def _control_path(output: Path, operation_id: str) -> Path:
    return output.parent / f".{output.name}.scope-extension-{operation_id}.json"


def cutover_scope_extension(staging: Path, *, fault: str | None = None) -> dict[str, Any]:
    staging = staging.resolve()
    state = _load_extension_state(staging)
    audit = json_load(staging / AUDIT_RELATIVE) if (staging / AUDIT_RELATIVE).is_file() else {}
    if state.get("status") != "ready" or audit.get("status") != "ready":
        raise _error("not-ready", "scope extension audit has not marked staging ready")
    output = Path(state["previous_output"]).resolve()
    if path_inside(staging, output) or path_inside(output, staging):
        raise _error("overlapping-output", "staging and production OUTPUT overlap")
    plan = json_load(staging / PLAN_RELATIVE)
    expected_origin = plan["preservation"]["origin_manifest"]
    actual_origin = _tree_manifest(output)
    if not _same_manifest(expected_origin, actual_origin):
        raise _error("origin-drift", "production OUTPUT changed after scope extension start")
    repository_state = preflight(Path(state["repository"]))
    if repository_state["commit"] != state["repository_commit"]:
        raise _error("target-drift", "target repository commit changed before cutover")
    operation_id = state["operation_id"]
    backup = output.parent / f".{output.name}.scope-extension-backup-{operation_id}"
    control_path = _control_path(output, operation_id)
    selection = _control_selection(output, actual_origin) if list(output.parent.glob(f".{output.name}.scope-extension-*.json")) else {"active": None}
    parent = selection.get("active")
    parent_record = parent[1] if parent else None
    previous_attempts: list[dict[str, Any]] = []
    if control_path.is_file() and not backup.exists():
        existing = json_load(control_path)
        if existing.get("status") == "cutover-failed-restored":
            previous_attempts = list(existing.get("attempts") or [])
            previous_attempts.append(
                {
                    "status": existing["status"],
                    "failure": existing.get("failure"),
                    "origin_restored": existing.get("origin_restored"),
                }
            )
        else:
            raise _error("cutover-conflict", "cutover control record already exists in a non-retryable state")
    if backup.exists():
        raise _error("cutover-conflict", "cutover backup or control record already exists")
    record = {
        "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
        "operation_id": operation_id,
        "status": "cutover-started",
        "parent_operation_id": parent_record.get("operation_id") if parent_record else None,
        "chain_depth": int(parent_record.get("chain_depth", 0)) + 1 if parent_record else 1,
        "output": str(output),
        "staging_output": str(staging),
        "backup_output": str(backup),
        "repository": state["repository"],
        "repository_commit": state["repository_commit"],
        "origin_manifest": expected_origin,
        "attempts": previous_attempts,
    }
    json_write(control_path, record)
    moved_staging = False
    try:
        # Some audit helpers use sqlite3 connection context managers whose
        # objects close only when released.  Collect before Windows directory
        # renames so verified databases do not retain transient file handles.
        _release_audit_handles()
        output.rename(backup)
        if fault == "after-backup-rename":
            raise OSError("injected failure after backup rename")
        backup_manifest = _tree_manifest(backup)
        if not _same_manifest(expected_origin, backup_manifest):
            raise _error("backup-verification", "renamed backup does not match the verified origin manifest")
        staging.rename(output)
        moved_staging = True
        if fault == "after-staging-rename":
            raise OSError("injected failure after staging rename")
        pipeline_status(output)
        sqlite_checks = _sqlite_checks(output)
        if not sqlite_checks or not all(item["passed"] for item in sqlite_checks):
            raise _error("cutover-verification", f"promoted SQLite verification failed: {sqlite_checks}")
        modified_manifest = _tree_manifest(output)
        record.update({
            "status": "cutover-complete",
            "backup_manifest": backup_manifest,
            "modified_manifest": modified_manifest,
            "sqlite": sqlite_checks,
        })
        json_write(control_path, record)
        return {
            "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
            "status": "cutover-complete",
            "operation_id": operation_id,
            "parent_operation_id": record["parent_operation_id"],
            "chain_depth": record["chain_depth"],
            "output": str(output),
            "backup_output": str(backup),
            "control": str(control_path),
            "sqlite": sqlite_checks,
        }
    except Exception as exc:
        try:
            if moved_staging and output.exists():
                output.rename(staging)
            if backup.exists() and not output.exists():
                backup.rename(output)
        finally:
            restored = output.is_dir() and _same_manifest(expected_origin, _tree_manifest(output))
            record.update({"status": "cutover-failed-restored" if restored else "cutover-failed", "failure": str(exc), "origin_restored": restored})
            json_write(control_path, record)
        if isinstance(exc, CkbError):
            raise
        raise _error("cutover-failed", str(exc)) from exc


def _active_control(output: Path) -> tuple[Path, dict[str, Any]]:
    selection = _control_selection(output)
    if selection["active"]:
        return selection["active"]
    rolled_back = selection["rolled_back_matches"]
    if len(rolled_back) == 1:
        value = rolled_back[0][1]
        value["idempotent_selection"] = True
        return rolled_back[0][0], value
    if len(rolled_back) > 1:
        raise _error("control-record", f"no active cutover; multiple rolled-back operations match current OUTPUT: {[item[1]['operation_id'] for item in rolled_back]}")
    raise _error("control-record", "no active cutover matches current OUTPUT")


def rollback_scope_extension(output: Path, *, fault: str | None = None) -> dict[str, Any]:
    output = output.resolve()
    control_path, record = _active_control(output)
    if record.get("status") == "rolled-back":
        actual = _tree_manifest(output)
        if not _same_manifest(record["origin_manifest"], actual):
            raise _error("rollback-drift", "rolled-back OUTPUT no longer matches its origin manifest")
        return {
            "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
            "status": "rolled-back",
            "operation_id": record["operation_id"],
            "reactivated_operation_id": None,
            "output": str(output),
            "idempotent": True,
        }
    actual_modified = _tree_manifest(output)
    if not _same_manifest(record["modified_manifest"], actual_modified):
        raise _error("modified-drift", "promoted OUTPUT changed after cutover; rollback guard stopped replacement")
    backup = Path(record["backup_output"])
    if not backup.is_dir() or not _same_manifest(record["origin_manifest"], _tree_manifest(backup)):
        raise _error("backup-verification", "cutover backup is missing or changed")
    rolled_forward = output.parent / f".{output.name}.scope-extension-modified-{record['operation_id']}"
    if rolled_forward.exists():
        raise _error("rollback-conflict", f"rollback quarantine already exists: {rolled_forward}")
    restored_origin = False
    try:
        _release_audit_handles()
        output.rename(rolled_forward)
        if fault == "after-modified-rename":
            raise OSError("injected failure after modified rename")
        backup.rename(output)
        restored_origin = True
        if fault == "after-backup-restore":
            raise OSError("injected failure after backup restore")
        restored = _tree_manifest(output)
        if not _same_manifest(record["origin_manifest"], restored):
            raise _error("rollback-verification", "restored OUTPUT differs from the pre-cutover byte manifest")
        sqlite_checks = _sqlite_checks(output)
        if not sqlite_checks or not all(item["passed"] for item in sqlite_checks):
            raise _error("rollback-sqlite", f"restored SQLite verification failed: {sqlite_checks}")
        parent_operation_id = record.get("parent_operation_id")
        if parent_operation_id:
            parent_matches = [
                value
                for _path, value in _control_records(output)
                if value.get("operation_id") == parent_operation_id
            ]
            if len(parent_matches) != 1 or parent_matches[0].get("status") != "cutover-complete" or not _same_manifest(parent_matches[0].get("modified_manifest", {}), restored):
                raise _error("rollback-parent", "restored OUTPUT does not match the recorded parent cutover")
        record.update({
            "status": "rolled-back",
            "rolled_forward_output": str(rolled_forward),
            "restored_manifest": restored,
            "rollback_sqlite": sqlite_checks,
            "reactivated_operation_id": parent_operation_id,
        })
        json_write(control_path, record)
        selected_after = _control_selection(output, restored)["active"]
        actual_reactivated = selected_after[1]["operation_id"] if selected_after else None
        if actual_reactivated != parent_operation_id:
            raise _error("rollback-parent", f"active parent mismatch after rollback: expected {parent_operation_id}, got {actual_reactivated}")
        return {
            "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
            "status": "rolled-back",
            "operation_id": record["operation_id"],
            "reactivated_operation_id": parent_operation_id,
            "output": str(output),
            "modified_output": str(rolled_forward),
            "control": str(control_path),
            "sqlite": sqlite_checks,
        }
    except Exception as exc:
        try:
            if restored_origin and output.exists():
                output.rename(backup)
            if rolled_forward.exists() and not output.exists():
                rolled_forward.rename(output)
        finally:
            restored_modified = output.is_dir() and _same_manifest(record["modified_manifest"], _tree_manifest(output))
            record.update({
                "status": "cutover-complete" if restored_modified else "rollback-failed",
                "last_rollback_failure": str(exc),
                "modified_restored": restored_modified,
            })
            json_write(control_path, record)
        if isinstance(exc, CkbError):
            raise
        raise _error("rollback-failed", str(exc)) from exc

"""Session-owned supervisor for the local CKB JSONL stdio server.

The short-lived Harness adapters never pretend to own a session process.  A
real CKB request starts one supervisor for a bounded lifecycle key; that
supervisor owns the stdio child, its pipes and reader threads until an explicit
session close or a reliable Harness parent PID disappears.
"""

from __future__ import annotations

from dataclasses import dataclass
import hashlib
import json
import os
from pathlib import Path
import queue
import shutil
import signal
import sqlite3
import subprocess
import sys
import threading
import time
from typing import Any, TextIO
import uuid

from .common import CkbError, background_process_options, json_load, json_write, utc_now
from .stdio_server import STDIO_RETRIEVAL_PROTOCOL, STDIO_RETRIEVAL_PROTOCOL_VERSION


SESSION_STDIO_SCHEMA_VERSION = 1
DEFAULT_START_TIMEOUT_SECONDS = 15.0
DEFAULT_REQUEST_TIMEOUT_SECONDS = 45.0
DEFAULT_CLOSE_TIMEOUT_SECONDS = 8.0
POLL_SECONDS = 0.025
WINDOWS_MAX_PATH_CHARS = 259
# The longest compact generated relative path is
# ``responses/<16-hex>.json.tmp`` (36 characters including separators).
# 223 + 36 = 259, the non-prefixed Windows path ceiling observed by the
# locked runtime.  Longer roots return an explicit structured fallback.
WINDOWS_LIFECYCLE_DIRECTORY_CHARS = 223
_FORBIDDEN_STATE_KEYS = {
    "prompt",
    "assistant",
    "assistant_message",
    "cookie",
    "credential",
    "password",
    "secret",
    "token",
    "transcript",
    "tool_input",
}


class _StartGate:
    def __init__(self) -> None:
        self.lock = threading.Lock()
        self.users = 0


_START_GATES_GUARD = threading.Lock()
_START_GATES: dict[str, _StartGate] = {}


def _retain_start_gate(key: str) -> _StartGate:
    with _START_GATES_GUARD:
        gate = _START_GATES.get(key)
        if gate is None:
            gate = _StartGate()
            _START_GATES[key] = gate
        gate.users += 1
        return gate


def _release_start_gate(key: str, gate: _StartGate) -> None:
    with _START_GATES_GUARD:
        gate.users -= 1
        if gate.users == 0 and _START_GATES.get(key) is gate:
            _START_GATES.pop(key, None)


def default_session_stdio_root() -> Path:
    configured = os.environ.get("CKB_SESSION_STDIO_ROOT")
    return (Path(configured).expanduser() if configured else Path.home() / ".ckb" / "session-stdio").resolve()


def _path_identity(path: Path | str) -> str:
    value = str(Path(path).expanduser().resolve()).replace("\\", "/").rstrip("/")
    return value.casefold() if os.name == "nt" else value


def _digest(*values: object) -> str:
    text = "\0".join(str(value) for value in values)
    return hashlib.sha256(text.encode("utf-8", errors="strict")).hexdigest()


def session_digest(session_id: str) -> str:
    value = session_id.strip()
    if not value:
        raise CkbError("session stdio requires a non-empty session id")
    return _digest("session", value)


def lifecycle_key(
    harness: str,
    session_id: str,
    output: Path,
    *,
    executable: Path | None = None,
    ckb: Path | None = None,
) -> str:
    python_value = executable or Path(sys.executable)
    ckb_value = ckb or Path(__file__).resolve().parents[1] / "ckb.py"
    identity = _digest(
        _path_identity(python_value),
        _path_identity(ckb_value),
        STDIO_RETRIEVAL_PROTOCOL,
        STDIO_RETRIEVAL_PROTOCOL_VERSION,
    )
    return "stdio-" + _digest(harness.strip().casefold(), session_digest(session_id), _path_identity(output), identity)


def _lifecycle_directory(root: Path, key: str) -> Path:
    return root.resolve() / key


def _lease_path(directory: Path) -> Path:
    return directory / "lease.json"


def _read_json(path: Path) -> dict[str, Any] | None:
    try:
        value = json_load(path)
        return value if isinstance(value, dict) else None
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        return None


def _validate_lifecycle_path_budget(directory: Path) -> dict[str, int]:
    characters = len(str(directory))
    if os.name == "nt" and characters > WINDOWS_LIFECYCLE_DIRECTORY_CHARS:
        raise CkbError(
            "session stdio lifecycle path budget exceeded: "
            f"directory_chars={characters}; directory_limit={WINDOWS_LIFECYCLE_DIRECTORY_CHARS}; "
            f"generated_path_limit={WINDOWS_MAX_PATH_CHARS}"
        )
    return {
        "directory_chars": characters,
        "directory_limit": WINDOWS_LIFECYCLE_DIRECTORY_CHARS,
        "generated_path_limit": WINDOWS_MAX_PATH_CHARS,
    }


def _write_lease(directory: Path, value: dict[str, Any], timeout: float = 3.0) -> None:
    """Replace lease state despite short Windows reader sharing conflicts."""

    path = _lease_path(directory)
    path.parent.mkdir(parents=True, exist_ok=True)
    _validate_lifecycle_path_budget(directory)
    temporary: Path | None = None
    for _attempt in range(32):
        candidate = directory / f".l{uuid.uuid4().hex[:6]}"
        try:
            with candidate.open("x", encoding="utf-8", newline="\n") as stream:
                stream.write(json.dumps(value, ensure_ascii=False, indent=2) + "\n")
            temporary = candidate
            break
        except FileExistsError:
            continue
    if temporary is None:
        raise CkbError("session stdio could not allocate a compact lease temporary file")
    deadline = time.monotonic() + timeout
    try:
        while True:
            try:
                os.replace(temporary, path)
                return
            except OSError as exc:
                sharing_conflict = os.name == "nt" and getattr(exc, "winerror", None) in {5, 32}
                if not sharing_conflict or time.monotonic() >= deadline:
                    raise
                time.sleep(POLL_SECONDS)
    finally:
        temporary.unlink(missing_ok=True)


def pid_exists(pid: int | None) -> bool:
    if not isinstance(pid, int) or pid <= 0:
        return False
    if pid == os.getpid():
        return True
    if os.name == "nt":
        try:
            import ctypes
            from ctypes import wintypes

            handle = ctypes.windll.kernel32.OpenProcess(0x00100000 | 0x1000, False, pid)
            if not handle:
                return False
            try:
                exit_code = wintypes.DWORD()
                if not ctypes.windll.kernel32.GetExitCodeProcess(handle, ctypes.byref(exit_code)):
                    return False
                return int(exit_code.value) == 259  # STILL_ACTIVE
            finally:
                ctypes.windll.kernel32.CloseHandle(handle)
        except Exception:
            return False
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except OSError:
        return False
    return True


def _force_terminate_pid(pid: int) -> bool:
    if not pid_exists(pid):
        return True
    if os.name == "nt":
        try:
            import ctypes

            process = ctypes.windll.kernel32.OpenProcess(0x0001 | 0x00100000, False, pid)
            if not process:
                return not pid_exists(pid)
            try:
                ctypes.windll.kernel32.TerminateProcess(process, 143)
                ctypes.windll.kernel32.WaitForSingleObject(process, 3000)
            finally:
                ctypes.windll.kernel32.CloseHandle(process)
            return not pid_exists(pid)
        except Exception:
            return False
    try:
        os.kill(pid, signal.SIGTERM)
    except ProcessLookupError:
        return True
    deadline = time.monotonic() + 2.0
    while pid_exists(pid) and time.monotonic() < deadline:
        time.sleep(POLL_SECONDS)
    if pid_exists(pid):
        try:
            os.kill(pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
    return not pid_exists(pid)


def process_metrics(pid: int | None = None) -> dict[str, Any]:
    """Return RSS and handle counts using only the locked runtime's stdlib."""

    process_id = int(pid or os.getpid())
    if os.name == "nt":
        import ctypes
        from ctypes import wintypes

        class PROCESS_MEMORY_COUNTERS(ctypes.Structure):
            _fields_ = [
                ("cb", wintypes.DWORD),
                ("PageFaultCount", wintypes.DWORD),
                ("PeakWorkingSetSize", ctypes.c_size_t),
                ("WorkingSetSize", ctypes.c_size_t),
                ("QuotaPeakPagedPoolUsage", ctypes.c_size_t),
                ("QuotaPagedPoolUsage", ctypes.c_size_t),
                ("QuotaPeakNonPagedPoolUsage", ctypes.c_size_t),
                ("QuotaNonPagedPoolUsage", ctypes.c_size_t),
                ("PagefileUsage", ctypes.c_size_t),
                ("PeakPagefileUsage", ctypes.c_size_t),
            ]

        handle = ctypes.windll.kernel32.OpenProcess(0x0400 | 0x0010, False, process_id)
        if not handle:
            raise CkbError(f"session stdio metrics cannot open process: pid={process_id}")
        try:
            counters = PROCESS_MEMORY_COUNTERS()
            counters.cb = ctypes.sizeof(counters)
            if not ctypes.windll.psapi.GetProcessMemoryInfo(handle, ctypes.byref(counters), counters.cb):
                raise CkbError(f"session stdio RSS metric is unavailable: pid={process_id}")
            count = wintypes.DWORD()
            if not ctypes.windll.kernel32.GetProcessHandleCount(handle, ctypes.byref(count)):
                raise CkbError(f"session stdio handle metric is unavailable: pid={process_id}")
            return {
                "pid": process_id,
                "rss_bytes": int(counters.WorkingSetSize),
                "handles": int(count.value),
                "source": "windows-kernel32-psapi",
            }
        finally:
            ctypes.windll.kernel32.CloseHandle(handle)
    status = Path(f"/proc/{process_id}/status")
    handles = Path(f"/proc/{process_id}/fd")
    if not status.is_file() or not handles.is_dir():
        raise CkbError(f"session stdio process metrics are unavailable: pid={process_id}")
    rss_line = next((line for line in status.read_text(encoding="utf-8").splitlines() if line.startswith("VmRSS:")), None)
    if rss_line is None:
        raise CkbError(f"session stdio RSS metric is unavailable: pid={process_id}")
    rss_bytes = int(rss_line.split()[1]) * 1024
    return {"pid": process_id, "rss_bytes": rss_bytes, "handles": len(list(handles.iterdir())), "source": "procfs"}


def _state_counts(
    *,
    lease: int,
    process: int,
    pending: int,
    readers: int,
    pipes: int,
) -> dict[str, int]:
    return {
        "active_leases": lease,
        "processes": process,
        "pending_requests": pending,
        "reader_threads": readers,
        "timers": 0,
        "listeners": 0,
        "pipes": pipes,
        "session_mappings": lease,
        "cache_references": lease,
    }


def _base_lease(
    *,
    key: str,
    harness: str,
    opaque_session: str,
    output: Path,
    executable: Path,
    ckb: Path,
    parent_pid: int | None,
    generation: str,
) -> dict[str, Any]:
    stamp = utc_now()
    return {
        "schema_version": SESSION_STDIO_SCHEMA_VERSION,
        "lifecycle_key": key,
        "generation": generation,
        "harness": harness.strip().casefold(),
        "session_digest": opaque_session,
        "output": str(output.resolve()),
        "state": "starting",
        "supervisor_pid": os.getpid(),
        "server_pid": None,
        "protocol": STDIO_RETRIEVAL_PROTOCOL,
        "protocol_version": STDIO_RETRIEVAL_PROTOCOL_VERSION,
        "executable_identity": _digest(_path_identity(executable), _path_identity(ckb)),
        "parent_pid": parent_pid,
        "parent_monitor": "pid" if parent_pid else "unavailable",
        "created_at_utc": stamp,
        "last_used_at_utc": stamp,
        "closed_at_utc": None,
        "fallback": {"active": False, "reason": None},
        "close_reason": None,
        "object_counts": _state_counts(lease=1, process=0, pending=0, readers=0, pipes=0),
    }


class _Reader(threading.Thread):
    def __init__(self, stream: TextIO, destination: queue.Queue[str] | list[str], name: str) -> None:
        super().__init__(name=name, daemon=False)
        self.stream = stream
        self.destination = destination

    def run(self) -> None:
        try:
            for line in self.stream:
                if isinstance(self.destination, queue.Queue):
                    self.destination.put(line)
                elif len(self.destination) < 200:
                    self.destination.append(line.rstrip("\r\n")[:2000])
        finally:
            if isinstance(self.destination, queue.Queue):
                self.destination.put("")


@dataclass
class _Transport:
    executable: Path
    ckb: Path
    output: Path
    process: subprocess.Popen[str] | None = None
    stdout_queue: queue.Queue[str] | None = None
    stdout_reader: _Reader | None = None
    stderr_reader: _Reader | None = None
    stderr_lines: list[str] | None = None
    pending: int = 0

    def start(self, timeout: float) -> dict[str, Any]:
        command = [str(self.executable), "-X", "utf8", str(self.ckb), "serve", "--stdio", "--out", str(self.output)]
        self.process = subprocess.Popen(
            command,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            errors="strict",
            bufsize=1,
            **background_process_options(),
        )
        assert self.process.stdout is not None and self.process.stderr is not None
        self.stdout_queue = queue.Queue()
        self.stderr_lines = []
        self.stdout_reader = _Reader(self.process.stdout, self.stdout_queue, "ckb-stdio-stdout")
        self.stderr_reader = _Reader(self.process.stderr, self.stderr_lines, "ckb-stdio-stderr")
        self.stdout_reader.start()
        self.stderr_reader.start()
        response = self.request({"id": "handshake", "method": "ping"}, timeout)
        result = response.get("result") if response.get("ok") else None
        if not isinstance(result, dict):
            raise CkbError("session stdio handshake did not return a result")
        if result.get("protocol") != STDIO_RETRIEVAL_PROTOCOL:
            raise CkbError("session stdio handshake protocol mismatch")
        if result.get("protocol_version") != STDIO_RETRIEVAL_PROTOCOL_VERSION:
            raise CkbError("session stdio handshake protocol version mismatch")
        if _path_identity(result.get("output", "")) != _path_identity(self.output):
            raise CkbError("session stdio handshake output mismatch")
        return response

    def request(self, request: dict[str, Any], timeout: float) -> dict[str, Any]:
        if self.process is None or self.process.poll() is not None:
            raise CkbError("session stdio child is not running")
        if self.process.stdin is None or self.stdout_queue is None:
            raise CkbError("session stdio child pipes are unavailable")
        self.pending += 1
        try:
            self.process.stdin.write(json.dumps(request, ensure_ascii=True, separators=(",", ":")) + "\n")
            self.process.stdin.flush()
            deadline = time.monotonic() + timeout
            while True:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise CkbError("session stdio response timeout")
                try:
                    line = self.stdout_queue.get(timeout=min(remaining, 0.1))
                except queue.Empty:
                    if self.process.poll() is not None:
                        raise CkbError("session stdio stdout closed before a response")
                    continue
                if not line:
                    raise CkbError("session stdio stdout reached EOF")
                try:
                    response = json.loads(line)
                except json.JSONDecodeError as exc:
                    raise CkbError("session stdio returned invalid JSON") from exc
                if not isinstance(response, dict) or response.get("id") != request.get("id"):
                    raise CkbError("session stdio response id mismatch")
                return response
        finally:
            self.pending -= 1

    def close(self, timeout: float) -> dict[str, Any]:
        process = self.process
        escalation = "already-exited"
        if process is not None and process.poll() is None:
            try:
                response = self.request({"id": "shutdown", "method": "shutdown"}, min(timeout, 2.0))
                escalation = "shutdown" if response.get("ok") else "shutdown-error"
            except Exception:
                escalation = "shutdown-error"
            try:
                process.wait(timeout=max(0.2, timeout / 2))
            except subprocess.TimeoutExpired:
                process.terminate()
                escalation = "terminate"
                try:
                    process.wait(timeout=max(0.2, timeout / 3))
                except subprocess.TimeoutExpired:
                    process.kill()
                    escalation = "kill"
                    process.wait(timeout=max(0.2, timeout / 3))
        if process is not None:
            for stream in (process.stdin, process.stdout, process.stderr):
                if stream is not None:
                    try:
                        stream.close()
                    except OSError:
                        pass
        for reader in (self.stdout_reader, self.stderr_reader):
            if reader is not None:
                reader.join(timeout=2.0)
        exit_code = process.returncode if process is not None else None
        pid = process.pid if process is not None else None
        stderr = list(self.stderr_lines or [])[-20:]
        self.process = None
        self.stdout_queue = None
        self.stdout_reader = None
        self.stderr_reader = None
        self.stderr_lines = None
        self.pending = 0
        return {"escalation": escalation, "server_pid": pid, "exit_code": exit_code, "stderr": stderr}


def _write_response(directory: Path, token: str, value: dict[str, Any]) -> None:
    json_write(directory / "responses" / f"{token}.json", value)


def _clear_transient(directory: Path) -> None:
    for name in ("requests", "responses", "control"):
        current = directory / name
        if not current.is_dir():
            continue
        for path in current.iterdir():
            try:
                if path.is_file():
                    path.unlink()
                elif path.is_dir():
                    shutil.rmtree(path)
            except OSError:
                pass


def controller_main(
    *,
    root: Path,
    key: str,
    harness: str,
    opaque_session: str,
    output: Path,
    executable: Path,
    ckb: Path,
    parent_pid: int | None,
    generation: str,
    start_timeout: float = DEFAULT_START_TIMEOUT_SECONDS,
    close_timeout: float = DEFAULT_CLOSE_TIMEOUT_SECONDS,
) -> dict[str, Any]:
    directory = _lifecycle_directory(root, key)
    path_budget = _validate_lifecycle_path_budget(directory)
    for name in ("requests", "responses", "control"):
        (directory / name).mkdir(parents=True, exist_ok=True)
    lease = _base_lease(
        key=key,
        harness=harness,
        opaque_session=opaque_session,
        output=output,
        executable=executable,
        ckb=ckb,
        parent_pid=parent_pid,
        generation=generation,
    )
    lease["path_budget"] = path_budget
    _write_lease(directory, lease)
    transport = _Transport(executable=executable, ckb=ckb, output=output)
    close_reason = "controller-stop"
    restart_budget = 1
    try:
        try:
            transport.start(start_timeout)
        except Exception as exc:
            close_info = transport.close(close_timeout)
            lease.update(
                {
                    "state": "fallback",
                    "fallback": {"active": True, "reason": f"startup:{type(exc).__name__}:{str(exc)[:300]}"},
                    "server_pid": None,
                    "object_counts": _state_counts(lease=1, process=0, pending=0, readers=0, pipes=0),
                    "close_detail": close_info,
                    "last_used_at_utc": utc_now(),
                }
            )
            _write_lease(directory, lease)
            return lease
        assert transport.process is not None
        lease.update(
            {
                "state": "ready",
                "server_pid": transport.process.pid,
                "object_counts": _state_counts(lease=1, process=1, pending=0, readers=2, pipes=3),
                "last_used_at_utc": utc_now(),
            }
        )
        _write_lease(directory, lease)
        while True:
            if parent_pid and not pid_exists(parent_pid):
                close_reason = "parent-death"
                break
            controls = sorted((directory / "control").glob("*.json"))
            if controls:
                control = _read_json(controls[0]) or {}
                close_reason = str(control.get("reason") or "explicit-close")[:120]
                break
            request_paths = sorted((directory / "requests").glob("*.json"))
            if not request_paths:
                time.sleep(POLL_SECONDS)
                continue
            request_path = request_paths[0]
            envelope = _read_json(request_path)
            if envelope is None:
                try:
                    request_path.unlink()
                except OSError:
                    pass
                continue
            token = str(envelope.get("request_token") or request_path.stem)
            request = envelope.get("request")
            if not isinstance(request, dict):
                _write_response(directory, token, {"status": "failed", "reason": "invalid-request-envelope"})
                request_path.unlink(missing_ok=True)
                continue
            lease["object_counts"] = _state_counts(lease=1, process=1, pending=1, readers=2, pipes=3)
            lease["last_used_at_utc"] = utc_now()
            _write_lease(directory, lease)
            response_value: dict[str, Any]
            try:
                response = transport.request(request, float(envelope.get("timeout_seconds") or DEFAULT_REQUEST_TIMEOUT_SECONDS))
                response_value = {
                    "schema_version": SESSION_STDIO_SCHEMA_VERSION,
                    "status": "passed" if response.get("ok") else "failed",
                    "mode": "resident-stdio",
                    "resident": True,
                    "lifecycle_key": key,
                    "generation": lease.get("generation"),
                    "supervisor_pid": os.getpid(),
                    "server_pid": transport.process.pid if transport.process else None,
                    "response": response,
                    "fallback": {"active": False, "reason": None},
                }
            except Exception as first_exc:
                response_value = {}
                if restart_budget > 0:
                    restart_budget -= 1
                    transport.close(close_timeout)
                    try:
                        transport.start(start_timeout)
                        assert transport.process is not None
                        lease["server_pid"] = transport.process.pid
                        response = transport.request(request, float(envelope.get("timeout_seconds") or DEFAULT_REQUEST_TIMEOUT_SECONDS))
                        response_value = {
                            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
                            "status": "passed" if response.get("ok") else "failed",
                            "mode": "resident-stdio",
                            "resident": True,
                            "lifecycle_key": key,
                            "generation": lease.get("generation"),
                            "supervisor_pid": os.getpid(),
                            "server_pid": transport.process.pid,
                            "response": response,
                            "fallback": {"active": False, "reason": None},
                            "restart_count": 1,
                        }
                    except Exception as second_exc:
                        response_value = {
                            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
                            "status": "transport-failed",
                            "mode": "cli-fallback-required",
                            "resident": False,
                            "lifecycle_key": key,
                            "supervisor_pid": os.getpid(),
                            "server_pid": None,
                            "fallback": {
                                "active": True,
                                "reason": f"request:{type(first_exc).__name__}:{str(first_exc)[:160]}; restart:{type(second_exc).__name__}:{str(second_exc)[:160]}",
                            },
                        }
                if not response_value:
                    response_value = {
                        "schema_version": SESSION_STDIO_SCHEMA_VERSION,
                        "status": "transport-failed",
                        "mode": "cli-fallback-required",
                        "resident": False,
                        "lifecycle_key": key,
                        "supervisor_pid": os.getpid(),
                        "server_pid": None,
                        "fallback": {"active": True, "reason": f"request:{type(first_exc).__name__}:{str(first_exc)[:300]}"},
                    }
            _write_response(directory, token, response_value)
            request_path.unlink(missing_ok=True)
            if response_value.get("status") == "transport-failed":
                lease["fallback"] = response_value["fallback"]
                close_reason = "transport-failed"
                break
            lease["object_counts"] = _state_counts(lease=1, process=1, pending=0, readers=2, pipes=3)
            lease["last_used_at_utc"] = utc_now()
            _write_lease(directory, lease)
    finally:
        lease["state"] = "closing"
        lease["close_reason"] = close_reason
        lease["object_counts"] = _state_counts(
            lease=1,
            process=1 if transport.process and transport.process.poll() is None else 0,
            pending=transport.pending,
            readers=sum(reader is not None for reader in (transport.stdout_reader, transport.stderr_reader)),
            pipes=3 if transport.process else 0,
        )
        _write_lease(directory, lease)
        close_detail = transport.close(close_timeout)
        lease.update(
            {
                "state": "closed",
                "server_pid": None,
                # Retain the supervisor PID until another process observes
                # that it has really exited; cleanup then clears the reference.
                "supervisor_pid": os.getpid(),
                "closed_at_utc": utc_now(),
                "last_used_at_utc": utc_now(),
                "close_detail": close_detail,
                "object_counts": _state_counts(lease=0, process=0, pending=0, readers=0, pipes=0),
            }
        )
        _write_lease(directory, lease)
        for path in (directory / "requests").glob("*.json"):
            envelope = _read_json(path) or {}
            token = str(envelope.get("request_token") or path.stem)
            _write_response(
                directory,
                token,
                {
                    "schema_version": SESSION_STDIO_SCHEMA_VERSION,
                    "status": "transport-failed",
                    "mode": "cli-fallback-required",
                    "resident": False,
                    "lifecycle_key": key,
                    "fallback": {"active": True, "reason": f"closed:{close_reason}"},
                },
            )
            path.unlink(missing_ok=True)
    return lease


def _supervisor_process_options() -> dict[str, Any]:
    if os.name == "nt":
        flags = getattr(subprocess, "CREATE_NO_WINDOW", 0) | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
        return {"creationflags": flags} if flags else {}
    return {"start_new_session": True}


def _reap_supervisor(process: subprocess.Popen[Any]) -> None:
    try:
        process.wait()
    except OSError:
        pass


def _acquire_start_lock(directory: Path, timeout: float) -> Any | None:
    lock = directory / "start.lock"
    deadline = time.monotonic() + timeout
    while time.monotonic() < deadline:
        handle = lock.open("a+b")
        try:
            if lock.stat().st_size == 0:
                handle.write(b"0")
                handle.flush()
            handle.seek(0)
            if os.name == "nt":
                import msvcrt

                msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
            else:
                import fcntl

                fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
            handle.seek(0)
            handle.write(
                json.dumps({"pid": os.getpid(), "created_at_utc": utc_now()}, separators=(",", ":")).encode("utf-8")
            )
            handle.truncate()
            handle.flush()
            return handle
        except OSError:
            handle.close()
            time.sleep(POLL_SECONDS)
    return None


def _release_start_lock(lock: Any | None) -> None:
    if lock is not None and not lock.closed:
        try:
            lock.seek(0)
            if os.name == "nt":
                import msvcrt

                msvcrt.locking(lock.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl

                fcntl.flock(lock.fileno(), fcntl.LOCK_UN)
        except OSError:
            pass
        finally:
            lock.close()


def _active_lease(directory: Path) -> dict[str, Any] | None:
    lease = _read_json(_lease_path(directory))
    if not lease:
        return None
    # The supervisor owns child health and the one permitted restart.  A dead
    # server with a live ready supervisor is therefore still the active lease;
    # clients must queue the request instead of racing a second supervisor.
    if lease.get("state") == "ready" and (
        pid_exists(lease.get("supervisor_pid")) or pid_exists(lease.get("server_pid"))
    ):
        return lease
    return None


def activate_session_stdio(
    *,
    harness: str,
    session_id: str,
    output: Path,
    root: Path | None = None,
    executable: Path | None = None,
    ckb: Path | None = None,
    parent_pid: int | None = None,
    start_timeout: float = DEFAULT_START_TIMEOUT_SECONDS,
) -> dict[str, Any]:
    """Start and handshake the lifecycle at the first exact Skill application."""

    output_value = output.expanduser().resolve()
    executable_value = (executable or Path(sys.executable)).expanduser().resolve()
    ckb_value = (ckb or Path(__file__).resolve().parents[1] / "ckb.py").expanduser().resolve()
    root_value = (root or default_session_stdio_root()).expanduser().resolve()
    normalized_harness = harness.strip().casefold()
    opaque_session = session_digest(session_id)
    key = lifecycle_key(normalized_harness, session_id, output_value, executable=executable_value, ckb=ckb_value)
    if not (output_value / "machine" / "knowledge.sqlite").is_file():
        return {
            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
            "status": "fallback",
            "mode": "cli-fallback",
            "resident": False,
            "created": False,
            "lifecycle_key": key,
            "generation": None,
            "supervisor_pid": None,
            "server_pid": None,
            "protocol": None,
            "protocol_version": None,
            "parent_monitor": "pid" if parent_pid else "unavailable",
            "fallback": {"active": True, "reason": "startup:machine-knowledge-missing"},
        }
    directory = _lifecycle_directory(root_value, key)
    root_value.mkdir(parents=True, exist_ok=True)
    try:
        lease = _active_lease(directory)
        created = lease is None
        if lease is None:
            lease = _start_supervisor(
                directory=directory,
                root=root_value,
                key=key,
                harness=normalized_harness,
                opaque_session=opaque_session,
                output=output_value,
                executable=executable_value,
                ckb=ckb_value,
                parent_pid=parent_pid,
                timeout=start_timeout,
            )
        return {
            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
            "status": "ready",
            "mode": "resident-stdio",
            "resident": True,
            "created": created,
            "lifecycle_key": key,
            "generation": lease.get("generation"),
            "supervisor_pid": lease.get("supervisor_pid"),
            "server_pid": lease.get("server_pid"),
            "protocol": lease.get("protocol"),
            "protocol_version": lease.get("protocol_version"),
            "parent_monitor": lease.get("parent_monitor"),
            "path_budget": lease.get("path_budget"),
            "fallback": {"active": False, "reason": None},
        }
    except Exception as exc:
        return {
            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
            "status": "fallback",
            "mode": "cli-fallback",
            "resident": False,
            "created": False,
            "lifecycle_key": key,
            "generation": None,
            "supervisor_pid": None,
            "server_pid": None,
            "protocol": None,
            "protocol_version": None,
            "parent_monitor": "pid" if parent_pid else "unavailable",
            "fallback": {"active": True, "reason": f"startup:{type(exc).__name__}:{str(exc)[:300]}"},
        }


def _activation_exists(output: Path, harness: str, session_id: str) -> bool:
    database = output.resolve() / "machine" / "automation.sqlite"
    if not database.is_file():
        return False
    try:
        connection = sqlite3.connect(f"file:{database.as_posix()}?mode=ro", uri=True)
        try:
            row = connection.execute(
                "SELECT 1 FROM skill_activations WHERE harness=? AND external_session_id=? AND skill_name=? LIMIT 1",
                (harness.strip().casefold(), session_id, "code-knowledge-builder"),
            ).fetchone()
            return row is not None
        finally:
            connection.close()
    except sqlite3.Error:
        return False


def _start_supervisor_locked(
    *,
    directory: Path,
    root: Path,
    key: str,
    harness: str,
    opaque_session: str,
    output: Path,
    executable: Path,
    ckb: Path,
    parent_pid: int | None,
    timeout: float,
) -> dict[str, Any]:
    _validate_lifecycle_path_budget(directory)
    directory.mkdir(parents=True, exist_ok=True)
    lock = _acquire_start_lock(directory, timeout)
    if lock is None:
        raise CkbError("session stdio single-flight start lock timeout")
    try:
        active = _active_lease(directory)
        if active:
            return active
        cleanup_sessions(root=root, only_key=key)
        previous = _read_json(_lease_path(directory)) or {}
        previous_pid = previous.get("supervisor_pid")
        previous_deadline = time.monotonic() + timeout
        while pid_exists(previous_pid) and time.monotonic() < previous_deadline:
            time.sleep(POLL_SECONDS)
        if pid_exists(previous_pid):
            raise CkbError("session stdio previous supervisor did not exit before restart")
        cleanup_sessions(root=root, only_key=key)
        generation = uuid.uuid4().hex[:16]
        log_root = directory / "logs"
        log_root.mkdir(parents=True, exist_ok=True)
        command = [
            str(executable),
            "-X",
            "utf8",
            str(ckb),
            "stdio-session",
            "_controller",
            "--root",
            str(root),
            "--key",
            key,
            "--harness",
            harness,
            "--session-digest",
            opaque_session,
            "--out",
            str(output),
            "--python",
            str(executable),
            "--ckb",
            str(ckb),
            "--generation",
            generation,
        ]
        if parent_pid:
            command.extend(["--parent-pid", str(parent_pid)])
        with (log_root / "supervisor.stdout.log").open("a", encoding="utf-8", newline="\n") as stdout_log, (
            log_root / "supervisor.stderr.log"
        ).open("a", encoding="utf-8", newline="\n") as stderr_log:
            process = subprocess.Popen(
                command,
                stdin=subprocess.DEVNULL,
                stdout=stdout_log,
                stderr=stderr_log,
                close_fds=True,
                **_supervisor_process_options(),
            )
        threading.Thread(
            target=_reap_supervisor,
            args=(process,),
            name=f"ckb-stdio-reap-{process.pid}",
            daemon=True,
        ).start()
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            lease = _read_json(_lease_path(directory))
            current_generation = lease.get("generation") if lease else None
            if (
                lease
                and current_generation == generation
                and lease.get("state") == "ready"
                and pid_exists(lease.get("server_pid"))
            ):
                return lease
            if lease and current_generation == generation and lease.get("state") in {"fallback", "closed"}:
                reason = (lease.get("fallback") or {}).get("reason") or lease.get("close_reason") or "startup-failed"
                raise CkbError(f"session stdio supervisor did not become ready: {reason}")
            if process.poll() is not None:
                raise CkbError(f"session stdio supervisor exited during start: exit={process.returncode}")
            time.sleep(POLL_SECONDS)
        raise CkbError("session stdio supervisor start timeout")
    finally:
        _release_start_lock(lock)


def _start_supervisor(**arguments: Any) -> dict[str, Any]:
    key = str(arguments["key"])
    timeout = float(arguments["timeout"])
    gate = _retain_start_gate(key)
    acquired = gate.lock.acquire(timeout=timeout)
    if not acquired:
        _release_start_gate(key, gate)
        raise CkbError("session stdio in-process single-flight timeout")
    try:
        return _start_supervisor_locked(**arguments)
    finally:
        gate.lock.release()
        _release_start_gate(key, gate)


def _fallback_command(executable: Path, ckb: Path, output: Path, request: dict[str, Any]) -> tuple[list[str] | None, str | None]:
    method = request.get("method")
    if method in {"retrieve", "brief"}:
        question = request.get("question")
        if not isinstance(question, str) or not question.strip():
            return None, "fallback-retrieve-requires-question"
        command = [str(executable), "-X", "utf8", str(ckb), str(method), "--out", str(output), question]
        command.extend(["--budget", str(request.get("budget", 1800 if method == "brief" else 1500))])
        command.extend(["--max-pages", str(request.get("max_pages", 8)), "--profile", str(request.get("profile", "fast"))])
        return command, None
    if method in {"entity", "source", "neighbors"}:
        selector = request.get("selector")
        if not isinstance(selector, str) or not selector.strip():
            return None, f"fallback-{method}-requires-selector"
        command = [str(executable), "-X", "utf8", str(ckb), str(method), "--out", str(output), selector]
        if method == "source":
            command.extend(["--context-lines", str(request.get("context_lines", 3))])
        elif method == "neighbors":
            command.extend(["--depth", str(request.get("depth", 1)), "--limit", str(request.get("limit", 50))])
            if request.get("relation"):
                command.extend(["--relation", str(request["relation"])])
        return command, None
    if method == "changes":
        command = [str(executable), "-X", "utf8", str(ckb), "changes", "--out", str(output), "--limit", str(request.get("limit", 20))]
        if request.get("kind"):
            command.extend(["--kind", str(request["kind"])])
        return command, None
    if method == "ping":
        return [], None
    return None, f"fallback-unsupported-method:{method}"


def _run_cli_fallback(
    *,
    executable: Path,
    ckb: Path,
    output: Path,
    request: dict[str, Any],
    reason: str,
    timeout: float,
) -> dict[str, Any]:
    command, error = _fallback_command(executable, ckb, output, request)
    if error:
        return {
            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
            "status": "failed",
            "mode": "cli-fallback",
            "resident": False,
            "fallback": {"active": True, "reason": reason},
            "error": {"type": "CkbError", "message": error, "exit_code": 2},
        }
    if command == []:
        return {
            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
            "status": "passed",
            "mode": "cli-fallback",
            "resident": False,
            "fallback": {"active": True, "reason": reason},
            "response": {
                "id": request.get("id"),
                "ok": True,
                "method": "ping",
                "result": {"status": "available-via-cli", "protocol": None, "protocol_version": None},
            },
        }
    environment = os.environ.copy()
    environment["CKB_STDIO_FALLBACK"] = "1"
    try:
        completed = subprocess.run(
            command,
            text=True,
            encoding="utf-8",
            errors="replace",
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=timeout,
            env=environment,
            **background_process_options(),
        )
    except subprocess.TimeoutExpired:
        return {
            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
            "status": "failed",
            "mode": "cli-fallback",
            "resident": False,
            "fallback": {"active": True, "reason": reason},
            "error": {"type": "TimeoutExpired", "message": "per-command CLI fallback timed out", "exit_code": 2},
        }
    try:
        value = json.loads(completed.stdout) if completed.stdout.strip() else None
    except json.JSONDecodeError:
        value = None
    ok = completed.returncode == 0 and isinstance(value, dict)
    return {
        "schema_version": SESSION_STDIO_SCHEMA_VERSION,
        "status": "passed" if ok else "failed",
        "mode": "cli-fallback",
        "resident": False,
        "fallback": {"active": True, "reason": reason},
        "response": {
            "id": request.get("id"),
            "ok": ok,
            "method": request.get("method"),
            "result": value if ok else None,
            "error": None
            if ok
            else {
                "type": "CliFallbackError",
                "message": (completed.stderr or completed.stdout or "fallback failed").strip()[:1000],
                "exit_code": completed.returncode,
            },
        },
        "cli_exit_status": completed.returncode,
    }


def request_session(
    *,
    harness: str,
    session_id: str,
    output: Path,
    request: dict[str, Any],
    root: Path | None = None,
    executable: Path | None = None,
    ckb: Path | None = None,
    parent_pid: int | None = None,
    start_timeout: float = DEFAULT_START_TIMEOUT_SECONDS,
    request_timeout: float = DEFAULT_REQUEST_TIMEOUT_SECONDS,
    require_activation: bool = True,
) -> dict[str, Any]:
    output_value = output.expanduser().resolve()
    executable_value = (executable or Path(sys.executable)).expanduser().resolve()
    ckb_value = (ckb or Path(__file__).resolve().parents[1] / "ckb.py").expanduser().resolve()
    root_value = (root or default_session_stdio_root()).expanduser().resolve()
    if not (output_value / "machine" / "knowledge.sqlite").is_file():
        raise CkbError(f"session stdio requires machine/knowledge.sqlite: {output_value}")
    if not executable_value.is_file() or not ckb_value.is_file():
        raise CkbError("session stdio executable identity is missing")
    if not isinstance(request, dict):
        raise CkbError("session stdio request must be one JSON object")
    request = dict(request)
    if not isinstance(request.get("id"), (str, int)) or isinstance(request.get("id"), bool):
        request["id"] = "request-" + uuid.uuid4().hex[:16]
    normalized_harness = harness.strip().casefold()
    if require_activation and not _activation_exists(output_value, normalized_harness, session_id):
        return {
            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
            "status": "ignored",
            "mode": "not-started",
            "resident": False,
            "reason": "skill-not-applied-in-session",
            "fallback": {"active": False, "reason": None},
        }
    opaque_session = session_digest(session_id)
    key = lifecycle_key(normalized_harness, session_id, output_value, executable=executable_value, ckb=ckb_value)
    directory = _lifecycle_directory(root_value, key)
    root_value.mkdir(parents=True, exist_ok=True)
    try:
        lease = _active_lease(directory)
        if lease is None:
            lease = _start_supervisor(
                directory=directory,
                root=root_value,
                key=key,
                harness=normalized_harness,
                opaque_session=opaque_session,
                output=output_value,
                executable=executable_value,
                ckb=ckb_value,
                parent_pid=parent_pid,
                timeout=start_timeout,
            )
    except Exception as exc:
        return _run_cli_fallback(
            executable=executable_value,
            ckb=ckb_value,
            output=output_value,
            request=request,
            reason=f"startup:{type(exc).__name__}:{str(exc)[:300]}",
            timeout=request_timeout,
        )
    token = uuid.uuid4().hex[:16]
    request_path = directory / "requests" / f"{token}.json"
    response_path = directory / "responses" / f"{token}.json"
    json_write(
        request_path,
        {
            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
            "request_token": token,
            "timeout_seconds": request_timeout,
            "created_at_utc": utc_now(),
            "request": request,
        },
    )
    deadline = time.monotonic() + request_timeout + 2.0
    try:
        while time.monotonic() < deadline:
            response = _read_json(response_path)
            if response is not None:
                if response.get("status") == "transport-failed":
                    reason = str((response.get("fallback") or {}).get("reason") or "transport-failed")
                    return _run_cli_fallback(
                        executable=executable_value,
                        ckb=ckb_value,
                        output=output_value,
                        request=request,
                        reason=reason,
                        timeout=request_timeout,
                    )
                return response
            current = _read_json(_lease_path(directory)) or lease
            if current.get("state") in {"fallback", "closed"} or not pid_exists(current.get("supervisor_pid")):
                reason = str((current.get("fallback") or {}).get("reason") or current.get("close_reason") or "supervisor-exited")
                return _run_cli_fallback(
                    executable=executable_value,
                    ckb=ckb_value,
                    output=output_value,
                    request=request,
                    reason=reason,
                    timeout=request_timeout,
                )
            time.sleep(POLL_SECONDS)
        return _run_cli_fallback(
            executable=executable_value,
            ckb=ckb_value,
            output=output_value,
            request=request,
            reason="client-response-timeout",
            timeout=request_timeout,
        )
    finally:
        request_path.unlink(missing_ok=True)
        response_path.unlink(missing_ok=True)


def environment_session() -> tuple[str, str, int | None] | None:
    """Resolve only documented or explicit Harness identity environment fields."""

    explicit_harness = str(os.environ.get("CKB_HARNESS") or "").strip().casefold()
    candidates = [
        ("codex", ("CODEX_SESSION_ID", "CODEX_THREAD_ID")),
        ("claude", ("CLAUDE_SESSION_ID",)),
        ("opencode", ("OPENCODE_SESSION_ID",)),
        ("dsh", ("DSH_SESSION_ID",)),
        ("gemini", ("GEMINI_SESSION_ID",)),
        ("copilot", ("COPILOT_SESSION_ID",)),
        ("cursor", ("CURSOR_SESSION_ID",)),
        ("generic", ("CKB_SESSION_ID",)),
    ]
    if explicit_harness:
        candidates.sort(key=lambda item: item[0] != explicit_harness)
    for harness, names in candidates:
        if explicit_harness and harness != explicit_harness:
            continue
        for name in ("CKB_SESSION_ID", *names):
            session = str(os.environ.get(name) or "").strip()
            if session:
                parent_text = str(os.environ.get("CKB_HARNESS_PID") or "").strip()
                parent_pid = int(parent_text) if parent_text.isdigit() and int(parent_text) > 0 else None
                return harness, session, parent_pid
    return None


def maybe_request_session(output: Path, request: dict[str, Any]) -> dict[str, Any] | None:
    """Route an ordinary CKB CLI query through an already activated session."""

    if os.environ.get("CKB_STDIO_FALLBACK") == "1":
        return None
    identity = environment_session()
    if identity is None:
        return None
    harness, session_id, parent_pid = identity
    if not _activation_exists(output.resolve(), harness, session_id):
        return None
    return request_session(
        harness=harness,
        session_id=session_id,
        output=output,
        request=request,
        parent_pid=parent_pid,
    )


def list_sessions(*, root: Path | None = None, active_only: bool = False) -> dict[str, Any]:
    root_value = (root or default_session_stdio_root()).expanduser().resolve()
    leases: list[dict[str, Any]] = []
    if root_value.is_dir():
        for path in sorted(root_value.glob("stdio-*/lease.json")):
            lease = _read_json(path)
            if not lease:
                continue
            active = lease.get("state") in {"starting", "ready", "closing"} and pid_exists(lease.get("supervisor_pid"))
            if active_only and not active:
                continue
            value = dict(lease)
            value["active"] = active
            leases.append(value)
    return {
        "schema_version": SESSION_STDIO_SCHEMA_VERSION,
        "status": "passed",
        "root": str(root_value),
        "count": len(leases),
        "active": sum(1 for item in leases if item["active"]),
        "leases": leases,
    }


def close_session(
    *,
    harness: str,
    session_id: str,
    output: Path,
    root: Path | None = None,
    reason: str = "explicit-close",
    timeout: float = DEFAULT_CLOSE_TIMEOUT_SECONDS,
) -> dict[str, Any]:
    root_value = (root or default_session_stdio_root()).expanduser().resolve()
    opaque = session_digest(session_id)
    output_identity = _path_identity(output)
    matches: list[Path] = []
    if root_value.is_dir():
        for path in root_value.glob("stdio-*/lease.json"):
            lease = _read_json(path)
            if not lease:
                continue
            if (
                lease.get("harness") == harness.strip().casefold()
                and lease.get("session_digest") == opaque
                and _path_identity(lease.get("output", "")) == output_identity
            ):
                matches.append(path.parent)
    closed: list[dict[str, Any]] = []
    for directory in sorted(matches):
        lease = _read_json(_lease_path(directory)) or {}
        if lease.get("state") == "closed" and not pid_exists(lease.get("supervisor_pid")) and not pid_exists(lease.get("server_pid")):
            closed.append({"lifecycle_key": lease.get("lifecycle_key"), "status": "already-closed"})
            continue
        token = uuid.uuid4().hex[:12]
        json_write(directory / "control" / f"c-{token}.json", {"reason": reason[:120], "requested_at_utc": utc_now()})
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            current = _read_json(_lease_path(directory)) or lease
            if (
                current.get("state") == "closed"
                and not pid_exists(current.get("server_pid"))
                and not pid_exists(current.get("supervisor_pid"))
            ):
                cleanup_sessions(root=root_value, only_key=str(current.get("lifecycle_key") or directory.name))
                current = _read_json(_lease_path(directory)) or current
                closed.append({"lifecycle_key": current.get("lifecycle_key"), "status": "closed", "lease": current})
                break
            if not pid_exists(current.get("supervisor_pid")):
                cleanup_sessions(root=root_value, only_key=str(current.get("lifecycle_key") or directory.name))
            time.sleep(POLL_SECONDS)
        else:
            current = _read_json(_lease_path(directory)) or lease
            _force_terminate_pid(int(current.get("supervisor_pid") or 0))
            _force_terminate_pid(int(current.get("server_pid") or 0))
            cleanup_sessions(root=root_value, only_key=str(current.get("lifecycle_key") or directory.name))
            closed.append({"lifecycle_key": current.get("lifecycle_key"), "status": "forced-cleanup"})
    return {
        "schema_version": SESSION_STDIO_SCHEMA_VERSION,
        "status": "closed" if matches else "not-found",
        "reason": reason[:120],
        "matched": len(matches),
        "closed": closed,
    }


def cleanup_sessions(*, root: Path | None = None, only_key: str | None = None) -> dict[str, Any]:
    root_value = (root or default_session_stdio_root()).expanduser().resolve()
    cleaned: list[dict[str, Any]] = []
    if not root_value.is_dir():
        return {"schema_version": SESSION_STDIO_SCHEMA_VERSION, "status": "passed", "root": str(root_value), "cleaned": []}
    directories = [root_value / only_key] if only_key else sorted(path for path in root_value.glob("stdio-*") if path.is_dir())
    for directory in directories:
        lease = _read_json(_lease_path(directory))
        if not lease:
            continue
        supervisor_pid = lease.get("supervisor_pid")
        server_pid = lease.get("server_pid")
        parent_pid = lease.get("parent_pid")
        parent_dead = bool(parent_pid) and not pid_exists(parent_pid)
        supervisor_dead = bool(supervisor_pid) and not pid_exists(supervisor_pid)
        if lease.get("state") in {"starting", "ready", "closing"} and pid_exists(supervisor_pid) and parent_dead:
            json_write(directory / "control" / f"c-{uuid.uuid4().hex[:12]}.json", {"reason": "parent-death-cleanup"})
            cleaned.append({"lifecycle_key": lease.get("lifecycle_key"), "action": "close-requested"})
            continue
        if (supervisor_dead or not supervisor_pid) and lease.get("state") in {"fallback", "closed"}:
            deadline = time.monotonic() + 1.5
            while pid_exists(server_pid) and time.monotonic() < deadline:
                time.sleep(POLL_SECONDS)
            forced = False
            if pid_exists(server_pid):
                forced = _force_terminate_pid(int(server_pid))
            lease.update(
                {
                    "state": "closed",
                    "supervisor_pid": None,
                    "server_pid": None,
                    "closed_at_utc": lease.get("closed_at_utc") or utc_now(),
                    "close_reason": lease.get("close_reason") or "stale-cleanup",
                    "object_counts": _state_counts(lease=0, process=0, pending=0, readers=0, pipes=0),
                }
            )
            _write_lease(directory, lease)
            _clear_transient(directory)
            cleaned.append({"lifecycle_key": lease.get("lifecycle_key"), "action": "stale-cleaned", "forced_server": forced})
    return {"schema_version": SESSION_STDIO_SCHEMA_VERSION, "status": "passed", "root": str(root_value), "cleaned": cleaned}


def audit_sessions(*, root: Path | None = None) -> dict[str, Any]:
    listing = list_sessions(root=root)
    errors: list[str] = []
    totals = _state_counts(lease=0, process=0, pending=0, readers=0, pipes=0)
    for lease in listing["leases"]:
        serialized = json.dumps(lease, ensure_ascii=False, sort_keys=True).casefold()
        for field in _FORBIDDEN_STATE_KEYS:
            if f'"{field}"' in serialized:
                errors.append(f"forbidden-state-field:{field}:{lease.get('lifecycle_key')}")
        counts = lease.get("object_counts") or {}
        if lease.get("active"):
            for name in totals:
                totals[name] += int(counts.get(name, 0))
        elif lease.get("state") == "closed" and any(int(counts.get(name, 0)) for name in totals):
            errors.append(f"closed-object-count:{lease.get('lifecycle_key')}")
        if lease.get("state") == "ready" and not pid_exists(lease.get("server_pid")):
            errors.append(f"ready-server-missing:{lease.get('lifecycle_key')}")
    return {
        "schema_version": SESSION_STDIO_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "root": listing["root"],
        "active": listing["active"],
        "object_counts": totals,
        "errors": errors,
    }

def close(self, timeout: float) -> dict[str, Any]:
        process = self.process
        escalation = "already-exited"
        if process is not None and process.poll() is None:
            try:
                response = self.request({"id": "shutdown", "method": "shutdown"}, min(timeout, 2.0))
                escalation = "shutdown" if response.get("ok") else "shutdown-error"
            except Exception:
                escalation = "shutdown-error"
            try:
                process.wait(timeout=max(0.2, timeout / 2))
            except subprocess.TimeoutExpired:
                process.terminate()
                escalation = "terminate"
                try:
                    process.wait(timeout=max(0.2, timeout / 3))
                except subprocess.TimeoutExpired:
                    process.kill()
                    escalation = "kill"
                    process.wait(timeout=max(0.2, timeout / 3))
        if process is not None:
            for stream in (process.stdin, process.stdout, process.stderr):
                if stream is not None:
                    try:
                        stream.close()
                    except OSError:
                        pass
        for reader in (self.stdout_reader, self.stderr_reader):
            if reader is not None:
                reader.join(timeout=2.0)
        exit_code = process.returncode if process is not None else None
        pid = process.pid if process is not None else None
        stderr = list(self.stderr_lines or [])[-20:]
        self.process = None
        self.stdout_queue = None
        self.stdout_reader = None
        self.stderr_reader = None
        self.stderr_lines = None
        self.pending = 0
        return {"escalation": escalation, "server_pid": pid, "exit_code": exit_code, "stderr": stderr}

def serve_stdio(
    output: Path,
    *,
    input_stream: TextIO | None = None,
    output_stream: TextIO | None = None,
    retrieve: Callable[..., dict[str, Any]] | None = None,
    record_explanation: Callable[[Path, dict[str, Any], dict[str, Any]], dict[str, Any]] | None = None,
) -> dict[str, Any]:
    """Serve newline-delimited retrieval requests until shutdown or EOF.

    The transport is deliberately local and single-threaded.  Every response
    is one compact JSON line, so a Harness can keep this process alive for one
    task without opening a port or introducing a service dependency.
    """

    output = output.resolve()
    if not (output / "machine/knowledge.sqlite").is_file():
        raise CkbError("machine knowledge is missing; run finalize or machine-reindex")
    if input_stream is None and hasattr(sys.stdin, "reconfigure"):
        sys.stdin.reconfigure(encoding="utf-8", errors="strict", newline="\n")
    if output_stream is None and hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8", errors="strict", newline="\n", write_through=True)
    source = input_stream or sys.stdin
    destination = output_stream or sys.stdout
    retrieve_value = retrieve or retrieve_machine
    record_value = record_explanation or _record_explanation
    retrievals: dict[str, dict[str, Any]] = {}
    handled = 0
    succeeded = 0
    failed = 0
    shutdown = False
    for raw_line in source:
        line = raw_line.strip()
        if not line:
            continue
        handled += 1
        request_id: Any = None
        method: Any = None
        started = time.perf_counter_ns()
        try:
            request = json.loads(line)
            if not isinstance(request, dict):
                raise CkbError("stdio request must be a JSON object")
            request_id = request.get("id")
            if not isinstance(request_id, (str, int)) or isinstance(request_id, bool):
                raise CkbError("stdio request id must be a string or integer")
            method = request.get("method")
            if method == "ping":
                result = {
                    "status": "ready",
                    "protocol": STDIO_RETRIEVAL_PROTOCOL,
                    "protocol_version": STDIO_RETRIEVAL_PROTOCOL_VERSION,
                    "output": str(output),
                    "methods": [
                        "ping",
                        "retrieve",
                        "brief",
                        "entity",
                        "neighbors",
                        "source",
                        "changes",
                        "record-explanation",
                        "shutdown",
                    ],
                }
            elif method in {"retrieve", "brief"}:
                question = request.get("question")
                if not isinstance(question, str) or not question.strip():
                    raise CkbError("stdio retrieve question must be a non-empty string")
                question = _utf8_safe(question).strip()
                budget = _integer(request.get("budget", 1500), "budget", 200, 1_000_000)
                max_pages = _integer(request.get("max_pages", 8), "max_pages", 1, 32)
                profile = request.get("profile", "fast")
                if profile not in {"fast", "precise"}:
                    raise CkbError("stdio retrieve profile must be fast or precise")
                keyword_fallback = _keyword_fallback_options(request)
                if keyword_fallback is None:
                    result = retrieve_value(output, question, budget, max_pages, profile)
                else:
                    result = retrieve_value(
                        output,
                        question,
                        budget,
                        max_pages,
                        profile,
                        keyword_fallback=keyword_fallback,
                    )
                if result.get("status") != "passed" or not result.get("pack"):
                    raise CkbError("stdio retrieve did not return a passed Agent pack")
                retrievals[str(request_id)] = {**result, "request_id": str(request_id)}
                if method == "brief":
                    result = compact_agent_brief(output, result)
            elif method == "entity":
                selector = request.get("selector")
                if not isinstance(selector, str) or not selector.strip():
                    raise CkbError("stdio entity selector must be a non-empty string")
                result = entity_lookup(output, _utf8_safe(selector).strip())
            elif method == "neighbors":
                selector = request.get("selector")
                if not isinstance(selector, str) or not selector.strip():
                    raise CkbError("stdio neighbors selector must be a non-empty string")
                depth = _integer(request.get("depth", 1), "depth", 1, 8)
                limit = _integer(request.get("limit", 50), "limit", 1, 500)
                relation = request.get("relation")
                if relation is not None and not isinstance(relation, str):
                    raise CkbError("stdio neighbors relation must be a string")
                result = neighbor_lookup(output, _utf8_safe(selector).strip(), depth, relation, limit)
            elif method == "source":
                selector = request.get("selector")
                if not isinstance(selector, str) or not selector.strip():
                    raise CkbError("stdio source selector must be a non-empty string")
                context_lines = _integer(request.get("context_lines", 3), "context_lines", 0, 100)
                result = source_lookup(output, _utf8_safe(selector).strip(), context_lines)
            elif method == "changes":
                kind = request.get("kind")
                if kind is not None and not isinstance(kind, str):
                    raise CkbError("stdio changes kind must be a string")
                limit = _integer(request.get("limit", 20), "limit", 1, 500)
                result = change_documents(output, kind, limit)
            elif method == "record-explanation":
                retrieval_id = request.get("retrieval_request_id")
                if not isinstance(retrieval_id, (str, int)) or isinstance(retrieval_id, bool):
                    raise CkbError("stdio record-explanation retrieval_request_id must be a string or integer")
                retrieval = retrievals.get(str(retrieval_id))
                if retrieval is None:
                    raise CkbError("stdio record-explanation requires a completed retrieval from this server session")
                result = record_value(output, request, retrieval)
            elif method == "shutdown":
                result = {"status": "shutting-down"}
                shutdown = True
            else:
                raise CkbError(
                    "stdio request method must be ping, retrieve, brief, entity, neighbors, source, "
                    "changes, record-explanation, or shutdown"
                )
            succeeded += 1
            _write_line(
                destination,
                {
                    "id": request_id,
                    "ok": True,
                    "method": method,
                    "elapsed_ms": round((time.perf_counter_ns() - started) / 1_000_000, 6),
                    "result": result,
                },
            )
        except (json.JSONDecodeError, CkbError) as exc:
            failed += 1
            _write_line(
                destination,
                {
                    "id": request_id,
                    "ok": False,
                    "method": method,
                    "elapsed_ms": round((time.perf_counter_ns() - started) / 1_000_000, 6),
                    "error": {
                        "type": type(exc).__name__,
                        "message": str(exc),
                        "exit_code": exc.exit_code if isinstance(exc, CkbError) else 2,
                    },
                },
            )
        except Exception as exc:
            failed += 1
            _write_line(
                destination,
                {
                    "id": request_id,
                    "ok": False,
                    "method": method,
                    "elapsed_ms": round((time.perf_counter_ns() - started) / 1_000_000, 6),
                    "error": {
                        "type": type(exc).__name__,
                        "message": str(exc),
                        "exit_code": 1,
                    },
                },
            )
        if shutdown:
            break
    return {
        "schema_version": 1,
        "status": "stopped",
        "protocol": STDIO_RETRIEVAL_PROTOCOL,
        "protocol_version": STDIO_RETRIEVAL_PROTOCOL_VERSION,
        "requests": handled,
        "succeeded": succeeded,
        "failed": failed,
        "shutdown_requested": shutdown,
    }

def audit_work_record_index(output: Path) -> dict[str, Any]:
    markdown = output / "markdown"
    human = output / "human"
    result = audit_work_record_root(markdown)
    errors = list(result["errors"])
    left = markdown / WORK_RECORD_INDEX
    right = human / WORK_RECORD_INDEX
    if not left.is_file() or not right.is_file():
        errors.append({"reason": "work-record-index-mirror-missing"})
    elif left.read_bytes() != right.read_bytes():
        errors.append({"reason": "work-record-index-mirror-differs"})
    return {**result, "status": "passed" if not errors else "failed", "errors": errors}

#!/usr/bin/env python3
"""Create reproducible core and Obsidian-plugin archives with strict boundaries."""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import sys
import zipfile
from pathlib import Path, PurePosixPath


VERSION = "5.4.0"
ROOT = Path(__file__).resolve().parents[1]
EXCLUDED_PARTS = {".git", "__pycache__", ".pytest_cache", ".mypy_cache"}
CORE_EXCLUDED_TOP_LEVEL = {"plugins"}
RUNTIME_PREFIX = ("assets", "runtime", "win-x64")
PLUGIN_ROOT = ROOT / "plugins" / "obsidian-code-knowledge-builder"
PLUGIN_FILES = ("main.js", "manifest.json", "styles.css", "LICENSE", "NOTICE.md", "build-record.json", "deploy.py")
CORE_REQUIRED_FILES = (
    "SKILL.md",
    "agents/openai.yaml",
    "scripts/ckb.py",
    "scripts/ckb_core/__init__.py",
    "references/workflow.md",
    "references/runtime.md",
    "toolchain.lock.json",
    "THIRD_PARTY_NOTICES.md",
)


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def source_files(include_runtime: bool) -> list[Path]:
    result: list[Path] = []
    for current, directories, filenames in os.walk(ROOT):
        directory = Path(current)
        retained_directories: list[str] = []
        for name in sorted(directories):
            relative = (directory / name).relative_to(ROOT)
            if any(part in EXCLUDED_PARTS for part in relative.parts):
                continue
            if relative.parts and relative.parts[0] in CORE_EXCLUDED_TOP_LEVEL:
                continue
            if not include_runtime and relative.parts[:3] == RUNTIME_PREFIX:
                continue
            retained_directories.append(name)
        directories[:] = retained_directories
        for name in sorted(filenames):
            path = directory / name
            relative = path.relative_to(ROOT)
            if path.suffix in {".pyc", ".pyo"}:
                continue
            result.append(path)
    return sorted(result, key=lambda item: item.relative_to(ROOT).as_posix())


def core_capabilities(kind: str) -> dict[str, bool]:
    return {
        "source_scanning": True,
        "machine_sqlite_knowledge": True,
        "deterministic_retrieval": True,
        "human_markdown_obsidian_vault": True,
        "logseq_projection": True,
        "local_scope_and_segmented_build": True,
        "agent_review_and_audit": True,
        "automation_adapters": True,
        "session_scoped_stdio": True,
        "bundled_offline_runtime": kind == "full-win-x64",
        "obsidian_companion_plugin": False,
    }


def validate_core_boundary() -> None:
    lite = {path.relative_to(ROOT).as_posix() for path in source_files(False)}
    full = {path.relative_to(ROOT).as_posix() for path in source_files(True)}
    missing = sorted(set(CORE_REQUIRED_FILES) - lite)
    if missing:
        raise RuntimeError(f"lite core capability files are absent: {missing}")
    if any(path == "plugins" or path.startswith("plugins/") for path in lite | full):
        raise RuntimeError("core distributions must not contain plugins/")
    if not lite < full:
        raise RuntimeError("full-win-x64 must strictly extend lite")
    unexpected = sorted(
        path for path in full - lite
        if not path.startswith("assets/runtime/win-x64/")
    )
    if unexpected:
        raise RuntimeError(f"full-win-x64 adds non-runtime files: {unexpected}")


def validate_full_payload(lock: dict) -> Path:
    payload_lock = lock.get("payload")
    if not isinstance(payload_lock, dict):
        raise RuntimeError("full payload lock is pending")
    relative = payload_lock.get("path")
    if not isinstance(relative, str):
        raise RuntimeError("full payload path is absent from the lock")
    path = (ROOT / relative).resolve()
    if not path.is_file():
        raise RuntimeError(f"full payload is absent: {path}")
    if path.stat().st_size != int(payload_lock.get("size", -1)):
        raise RuntimeError("full payload size differs from toolchain.lock.json")
    actual_hash = sha256(path)
    if actual_hash != payload_lock.get("sha256"):
        raise RuntimeError("full payload SHA-256 differs from toolchain.lock.json")
    for required in payload_lock.get("required_members", []):
        with zipfile.ZipFile(path) as archive:
            if required not in archive.namelist():
                raise RuntimeError(f"full payload member is absent: {required}")
    return path


def build_core(kind: str, dist: Path) -> dict:
    lock = json.loads((ROOT / "toolchain.lock.json").read_text(encoding="utf-8"))
    validate_core_boundary()
    include_runtime = kind == "full-win-x64"
    if include_runtime:
        validate_full_payload(lock)
    files = source_files(include_runtime)
    manifest = {
        "schema_version": 1,
        "name": "code-knowledge-builder",
        "version": VERSION,
        "distribution": kind,
        "category": "core",
        "capabilities": core_capabilities(kind),
        "extends": "lite" if include_runtime else None,
        "forbidden_prefixes": ["plugins/"],
        "only_adds_prefix": "assets/runtime/win-x64/" if include_runtime else None,
        "toolchain_lock_id": lock["lock_id"],
        "files": [
            {
                "path": path.relative_to(ROOT).as_posix(),
                "size": path.stat().st_size,
                "sha256": sha256(path),
            }
            for path in files
        ],
    }
    dist.mkdir(parents=True, exist_ok=True)
    archive_path = dist / f"code-knowledge-builder-{kind}-{VERSION}.zip"
    if archive_path.exists():
        archive_path.unlink()
    prefix = PurePosixPath("code-knowledge-builder")
    with zipfile.ZipFile(archive_path, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for path in files:
            relative = PurePosixPath(path.relative_to(ROOT).as_posix())
            info = zipfile.ZipInfo(str(prefix / relative), date_time=(2026, 8, 26, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o100644 << 16
            archive.writestr(info, path.read_bytes(), compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)
        manifest_info = zipfile.ZipInfo(str(prefix / "distribution" / "release-manifest.json"), date_time=(2026, 8, 26, 0, 0, 0))
        manifest_info.compress_type = zipfile.ZIP_DEFLATED
        manifest_info.external_attr = 0o100644 << 16
        archive.writestr(manifest_info, json.dumps(manifest, ensure_ascii=False, indent=2).encode("utf-8") + b"\n")
    with zipfile.ZipFile(archive_path) as archive:
        bad_member = archive.testzip()
        if bad_member:
            raise RuntimeError(f"ZIP CRC failed: {bad_member}")
        archived_manifest = json.loads(archive.read(str(prefix / "distribution" / "release-manifest.json")))
        if archived_manifest != manifest:
            raise RuntimeError("archived release manifest differs from the generated manifest")
    result = {
        "status": "passed",
        "distribution": kind,
        "archive": str(archive_path.resolve()),
        "size": archive_path.stat().st_size,
        "sha256": sha256(archive_path),
        "file_count": len(files),
    }
    (dist / f"code-knowledge-builder-{kind}-{VERSION}.manifest.json").write_text(
        json.dumps({**result, "content": manifest}, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    return result


def validate_plugin_dist() -> tuple[str, list[Path], dict]:
    dist = PLUGIN_ROOT / "dist"
    files = [dist / name for name in PLUGIN_FILES]
    missing = [path.name for path in files if not path.is_file() or path.stat().st_size == 0]
    if missing:
        raise RuntimeError(f"Obsidian plugin dist files are absent: {missing}")
    manifest = json.loads((dist / "manifest.json").read_text(encoding="utf-8"))
    version = manifest.get("version")
    if not isinstance(version, str) or not version.strip():
        raise RuntimeError("Obsidian plugin version is absent from manifest.json")
    build_record = json.loads((dist / "build-record.json").read_text(encoding="utf-8"))
    if build_record.get("status") != "passed":
        raise RuntimeError("Obsidian plugin build-record.json has not passed")
    recorded = {item["path"]: item for item in build_record.get("files", [])}
    for path in files:
        if path.name == "build-record.json":
            continue
        item = recorded.get(path.name)
        if not item:
            raise RuntimeError(f"Obsidian plugin build record is missing: {path.name}")
        if int(item.get("size", -1)) != path.stat().st_size or item.get("sha256") != sha256(path):
            raise RuntimeError(f"Obsidian plugin dist differs from build record: {path.name}")
    return version, files, build_record


def build_plugin(dist: Path) -> dict:
    version, files, build_record = validate_plugin_dist()
    manifest = {
        "schema_version": 1,
        "name": "code-knowledge-builder-obsidian",
        "version": version,
        "distribution": "obsidian-plugin",
        "category": "plugin",
        "requires": {
            "knowledge_base": "CKB output with machine/knowledge.sqlite",
            "core_package": "installed separately",
        },
        "bundled_core": False,
        "bundled_offline_runtime": False,
        "agent_deploy": {
            "standalone": "python deploy.py deploy --vault VAULT",
            "core": "ckb.py obsidian-plugin register/deploy/status/remove",
            "auto_deploy_after_registration": True,
        },
        "files": [
            {"path": path.name, "size": path.stat().st_size, "sha256": sha256(path)}
            for path in files
        ],
        "upstream_commit": build_record.get("claudian_commit"),
    }
    dist.mkdir(parents=True, exist_ok=True)
    archive_path = dist / f"code-knowledge-builder-obsidian-{version}.zip"
    if archive_path.exists():
        archive_path.unlink()
    with zipfile.ZipFile(archive_path, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for path in files:
            info = zipfile.ZipInfo(path.name, date_time=(2026, 8, 30, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o100644 << 16
            archive.writestr(info, path.read_bytes(), compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)
    with zipfile.ZipFile(archive_path) as archive:
        bad_member = archive.testzip()
        if bad_member:
            raise RuntimeError(f"Obsidian plugin ZIP CRC failed: {bad_member}")
        if archive.namelist() != list(PLUGIN_FILES):
            raise RuntimeError("Obsidian plugin ZIP member set or order differs")
        for path in files:
            if archive.read(path.name) != path.read_bytes():
                raise RuntimeError(f"Obsidian plugin ZIP bytes differ: {path.name}")
    result = {
        "status": "passed",
        "distribution": "obsidian-plugin",
        "archive": str(archive_path.resolve()),
        "size": archive_path.stat().st_size,
        "sha256": sha256(archive_path),
        "file_count": len(files),
    }
    (dist / f"code-knowledge-builder-obsidian-{version}.manifest.json").write_text(
        json.dumps({**result, "content": manifest}, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    return result


def build(kind: str, dist: Path) -> dict:
    if kind == "obsidian-plugin":
        return build_plugin(dist)
    return build_core(kind, dist)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--kind",
        choices=("lite", "full-win-x64", "obsidian-plugin", "both", "all"),
        required=True,
    )
    parser.add_argument("--dist", type=Path, required=True)
    args = parser.parse_args()
    if args.kind == "both":
        kinds = ("lite", "full-win-x64")
    elif args.kind == "all":
        kinds = ("lite", "full-win-x64", "obsidian-plugin")
    else:
        kinds = (args.kind,)
    results = []
    try:
        for kind in kinds:
            results.append(build(kind, args.dist.resolve()))
    except RuntimeError as exc:
        print(json.dumps({"status": "pending", "reason": str(exc), "completed": results}, ensure_ascii=False, indent=2), file=sys.stderr)
        return 3
    print(json.dumps({"status": "passed", "results": results}, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

def source_files(include_runtime: bool) -> list[Path]:
    result: list[Path] = []
    for current, directories, filenames in os.walk(ROOT):
        directory = Path(current)
        retained_directories: list[str] = []
        for name in sorted(directories):
            relative = (directory / name).relative_to(ROOT)
            if any(part in EXCLUDED_PARTS for part in relative.parts):
                continue
            if relative.parts and relative.parts[0] in CORE_EXCLUDED_TOP_LEVEL:
                continue
            if not include_runtime and relative.parts[:3] == RUNTIME_PREFIX:
                continue
            retained_directories.append(name)
        directories[:] = retained_directories
        for name in sorted(filenames):
            path = directory / name
            relative = path.relative_to(ROOT)
            if path.suffix in {".pyc", ".pyo"}:
                continue
            result.append(path)
    return sorted(result, key=lambda item: item.relative_to(ROOT).as_posix())

def create_gap(output: Path, kind: str, summary_path: Path, evidence_paths: list[str]) -> dict[str, Any]:
    output = output.resolve()
    if not (output / "state.json").is_file():
        raise CkbError(f"CKB output is required: {output}")
    if kind not in GAP_KINDS:
        raise CkbError(f"gap kind must be one of: {list(GAP_KINDS)}")
    summary = _narrative(summary_path.resolve(), "gap summary")
    evidence = _evidence(output, evidence_paths, "gap")
    gap_id = stable_id("gap", kind, summary, *evidence)
    path = _record_path(output, gap_id)
    if path.is_file():
        value = json_load(path)
        return {**value, "idempotent": True, "record": str(path.resolve()), "index": str((_root(output) / "index.json").resolve())}
    stamp = utc_now()
    value = {
        "schema_version": GAP_SCHEMA_VERSION, "gap_id": gap_id, "kind": kind,
        "status": "deferred" if kind == "deferred-feedback" else "open",
        "summary_zh": summary, "evidence_paths": evidence, "created_at_utc": stamp,
        "updated_at_utc": stamp, "resolution_zh": None, "resolution_evidence_paths": [],
    }
    json_write(path, value)
    _write_index(output)
    _sync_indexes(output)
    audit = audit_gap_register(output)
    if audit["status"] != "passed":
        raise CkbError(f"research gap audit failed: {audit['errors'][:10]}")
    return {**value, "idempotent": False, "record": str(path.resolve()), "index": str((_root(output) / "index.json").resolve()), "audit": audit}

def _canonical_entry(value: str) -> str:
    value = value.strip()
    if "#" not in value:
        raise _error("entry-shape", f"new entry must use LANGUAGE:PATH#QUALIFIED_NAME: {value}")
    left, qualified = value.split("#", 1)
    if ":" not in left:
        raise _error("entry-shape", f"new entry must use LANGUAGE:PATH#QUALIFIED_NAME: {value}")
    language, path = left.split(":", 1)
    language = language.strip().casefold()
    normalized_path = PurePosixPath(path.replace("\\", "/").strip("/"))
    if language not in SUPPORTED_LANGUAGES:
        raise _error("unsupported-language", f"entry language is not supported: {language}")
    if not path or normalized_path.is_absolute() or ".." in normalized_path.parts:
        raise _error("entry-path", f"entry path must be a repository-relative source path: {path}")
    if not qualified.strip():
        raise _error("entry-qualified-name", "entry qualified name must not be empty")
    return f"{language}:{normalized_path.as_posix()}#{qualified.strip()}"

def _tree_manifest(root: Path) -> dict[str, Any]:
    root = root.resolve()
    if not root.is_dir():
        raise _error("output-missing", f"directory does not exist: {root}")
    files: list[dict[str, Any]] = []
    for path in sorted((item for item in root.rglob("*") if item.is_file()), key=lambda item: item.relative_to(root).as_posix()):
        relative = path.relative_to(root).as_posix()
        files.append({"path": relative, "size": path.stat().st_size, "sha256": sha256_file(path)})
    canonical = json.dumps(files, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return {
        "algorithm": "sha256-tree-v1",
        "file_count": len(files),
        "byte_count": sum(int(item["size"]) for item in files),
        "sha256": hashlib.sha256(canonical).hexdigest(),
        "files": files,
    }

def _sqlite_checks(output: Path) -> list[dict[str, Any]]:
    checks: list[dict[str, Any]] = []
    for relative in ("machine/knowledge.sqlite", "agent-index.sqlite", "machine/automation.sqlite"):
        path = output / relative
        if not path.is_file():
            if relative == "machine/automation.sqlite":
                continue
            checks.append({"path": relative, "integrity_check": "missing", "foreign_key_errors": None, "passed": False})
            continue
        connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
        try:
            integrity = str(connection.execute("PRAGMA integrity_check").fetchone()[0])
            foreign_keys = connection.execute("PRAGMA foreign_key_check").fetchall()
        finally:
            connection.close()
        checks.append({
            "path": relative,
            "integrity_check": integrity,
            "foreign_key_errors": [list(row) for row in foreign_keys],
            "passed": integrity == "ok" and not foreign_keys,
        })
    return checks

def _candidate_graph(output: Path) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    state = json_load(output / "state.json")
    entities: dict[str, dict[str, Any]] = {}
    links: dict[str, dict[str, Any]] = {}
    for batch in state["parse_batches"]:
        candidate = json_load(output / "chunks" / batch["id"] / "candidate.json")
        entities.update((item["id"], item) for item in candidate.get("entities", []))
        links.update((item["id"], item) for item in candidate.get("links", []))
    return [entities[key] for key in sorted(entities)], [links[key] for key in sorted(links)]

def _dimension(old_values: set[str], new_values: set[str]) -> dict[str, Any]:
    return {
        "retained": sorted(old_values & new_values),
        "added": sorted(new_values - old_values),
        "removed": sorted(old_values - new_values),
        "counts": {
            "retained": len(old_values & new_values),
            "added": len(new_values - old_values),
            "removed": len(old_values - new_values),
        },
    }

def _replace_prefix(value: Any, old: str, new: str) -> Any:
    if isinstance(value, dict):
        return {key: _replace_prefix(item, old, new) for key, item in value.items()}
    if isinstance(value, list):
        return [_replace_prefix(item, old, new) for item in value]
    if isinstance(value, str):
        return value.replace(old, new).replace(old.replace("\\", "/"), new.replace("\\", "/"))
    return value

def _rebind_preserved_json(staging: Path, previous_output: Path, mutable_files: list[dict[str, Any]]) -> list[str]:
    changed: list[str] = []
    old = str(previous_output.resolve())
    new = str(staging.resolve())
    for item in mutable_files:
        relative = str(item.get("relative_target") or "")
        path = staging / relative
        if path.suffix.casefold() != ".json" or not path.is_file():
            continue
        try:
            value = json_load(path)
        except (CkbError, OSError, UnicodeError, json.JSONDecodeError):
            continue
        updated = _replace_prefix(value, old, new)
        if updated != value:
            json_write(path, updated)
            changed.append(relative)
        item["post_extension_sha256"] = sha256_file(path)
        item["post_extension_size"] = path.stat().st_size
    return sorted(changed)

def _layer_inventory(output: Path, mutable_files: list[dict[str, Any]] | None = None) -> dict[str, Any]:
    gaps = list((output / "workspace-meta/gaps/records").glob("gap-*.json"))
    gap_statuses: dict[str, int] = {}
    for path in gaps:
        status = str(json_load(path).get("status"))
        gap_statuses[status] = gap_statuses.get(status, 0) + 1
    manifests = list((output / "references/manifests").glob("*.json"))
    reference_statuses: dict[str, int] = {}
    for path in manifests:
        status = str(json_load(path).get("status"))
        reference_statuses[status] = reference_statuses.get(status, 0) + 1
    records = mutable_files or []
    return {
        "work_record_count": len(list((output / "workspace-meta/notes").glob("*.json"))),
        "reference_count": len(manifests),
        "reference_statuses": dict(sorted(reference_statuses.items())),
        "gap_count": len(gaps),
        "gap_statuses": dict(sorted(gap_statuses.items())),
        "feedback_count": len(list((output / "workspace-meta/feedback").glob("*/*.json"))),
        "operation_shard_count": len(list((output / "workspace-meta/operations").glob("*.jsonl"))),
        "vault_user_files": sorted(
            item["relative_target"]
            for item in records
            if item.get("kind") == "vault-user-file"
        ),
    }

def _recomputed_review_sets(staging: Path, old_graph: dict[str, Any]) -> tuple[set[str], set[str], set[str]]:
    new_entities, _sources = _selected_entities(staging)
    _candidate_entities, candidate_links = _candidate_graph(staging)
    old_links = {item["id"]: item for item in old_graph.get("links", [])}
    new_links = {item["id"]: item for item in candidate_links}
    added_relation_ids = set(new_links) - set(old_links)
    affected_ids = {
        endpoint
        for relation_id in added_relation_ids
        for endpoint in (new_links[relation_id].get("source"), new_links[relation_id].get("target"))
        if endpoint
    }
    catalog = json_load(staging / "catalog.json")
    reuse_paths = set((catalog.get("migration_reuse") or {}).get("reused_file_paths", []))
    old_by_key = {_entity_key(entity): entity for entity in old_graph.get("entities", [])}
    reusable: set[str] = set()
    for entity in new_entities:
        previous = old_by_key.get(_entity_key(entity))
        if (
            entity["path"] in reuse_paths
            and entity["id"] not in affected_ids
            and previous
            and previous.get("review_status") == "agent-reviewed"
            and _review_shape(previous.get("classification")) == _review_shape(entity.get("classification"))
        ):
            reusable.add(entity["id"])
    selected = {item["id"] for item in new_entities}
    return reusable, selected - reusable, added_relation_ids

def _load_extension_state(output: Path) -> dict[str, Any]:
    path = output.resolve() / STATE_RELATIVE
    if not path.is_file():
        raise _error("state-missing", f"scope extension state does not exist: {path}")
    value = json_load(path)
    if value.get("schema_version") != SCOPE_EXTENSION_SCHEMA_VERSION:
        raise _error("state-schema", "scope extension state schema is unsupported")
    if Path(str(value.get("staging_output"))).resolve() != output.resolve():
        raise _error("absolute-binding", "state staging_output does not match the requested output")
    return value

def _control_records(output: Path) -> list[tuple[Path, dict[str, Any]]]:
    """Load and validate the immutable control history for one OUTPUT name.

    Legacy schema-1 records did not persist parent_operation_id.  Their parent
    is inferred only when exactly one older modified manifest equals the
    child's origin manifest.  New records persist that same relation and depth.
    """
    output = output.resolve()
    records: list[tuple[Path, dict[str, Any]]] = []
    by_id: dict[str, tuple[Path, dict[str, Any]]] = {}
    for path in sorted(output.parent.glob(f".{output.name}.scope-extension-*.json")):
        value = json_load(path)
        operation_id = str(value.get("operation_id") or "")
        if value.get("schema_version") != SCOPE_EXTENSION_SCHEMA_VERSION or not operation_id:
            raise _error("control-record-drift", f"control record schema or operation id is invalid: {path}")
        if path != _control_path(output, operation_id):
            raise _error("control-record-drift", f"control record path does not match operation id: {path}")
        if Path(str(value.get("output") or "")).resolve() != output:
            raise _error("control-record-drift", f"control record OUTPUT binding drifted: {path}")
        if operation_id in by_id:
            raise _error("control-record-drift", f"duplicate control operation id: {operation_id}")
        item = json.loads(json.dumps(value))
        records.append((path, item))
        by_id[operation_id] = (path, item)

    for path, value in records:
        origin = value.get("origin_manifest")
        if not isinstance(origin, dict):
            raise _error("control-record-drift", f"control origin manifest is missing: {path}")
        inferred = [
            candidate
            for _candidate_path, candidate in records
            if candidate.get("operation_id") != value.get("operation_id")
            and isinstance(candidate.get("modified_manifest"), dict)
            and _same_manifest(candidate["modified_manifest"], origin)
        ]
        if "parent_operation_id" in value:
            parent_id = value.get("parent_operation_id")
            if parent_id is not None:
                parent = by_id.get(str(parent_id))
                if parent is None or not isinstance(parent[1].get("modified_manifest"), dict) or not _same_manifest(parent[1]["modified_manifest"], origin):
                    raise _error("control-record-drift", f"parent operation does not produce the child origin: {path}")
        else:
            if len(inferred) > 1:
                raise _error("control-record-drift", f"legacy parent operation is ambiguous: {path}")
            parent_id = inferred[0]["operation_id"] if inferred else None
        value["parent_operation_id"] = parent_id

    depths: dict[str, int] = {}

    def depth(operation_id: str, trail: set[str]) -> int:
        if operation_id in depths:
            return depths[operation_id]
        if operation_id in trail:
            raise _error("control-record-drift", f"control parent cycle includes: {operation_id}")
        value = by_id[operation_id][1]
        parent_id = value.get("parent_operation_id")
        result = 1 if parent_id is None else depth(str(parent_id), {*trail, operation_id}) + 1
        recorded = value.get("chain_depth")
        if recorded is not None and int(recorded) != result:
            raise _error("control-record-drift", f"control chain depth drifted: {operation_id}")
        value["chain_depth"] = result
        depths[operation_id] = result
        return result

    for _path, value in records:
        depth(str(value["operation_id"]), set())
    return records

def _active_control(output: Path) -> tuple[Path, dict[str, Any]]:
    selection = _control_selection(output)
    if selection["active"]:
        return selection["active"]
    rolled_back = selection["rolled_back_matches"]
    if len(rolled_back) == 1:
        value = rolled_back[0][1]
        value["idempotent_selection"] = True
        return rolled_back[0][0], value
    if len(rolled_back) > 1:
        raise _error("control-record", f"no active cutover; multiple rolled-back operations match current OUTPUT: {[item[1]['operation_id'] for item in rolled_back]}")
    raise _error("control-record", "no active cutover matches current OUTPUT")

def rollback_scope_extension(output: Path, *, fault: str | None = None) -> dict[str, Any]:
    output = output.resolve()
    control_path, record = _active_control(output)
    if record.get("status") == "rolled-back":
        actual = _tree_manifest(output)
        if not _same_manifest(record["origin_manifest"], actual):
            raise _error("rollback-drift", "rolled-back OUTPUT no longer matches its origin manifest")
        return {
            "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
            "status": "rolled-back",
            "operation_id": record["operation_id"],
            "reactivated_operation_id": None,
            "output": str(output),
            "idempotent": True,
        }
    actual_modified = _tree_manifest(output)
    if not _same_manifest(record["modified_manifest"], actual_modified):
        raise _error("modified-drift", "promoted OUTPUT changed after cutover; rollback guard stopped replacement")
    backup = Path(record["backup_output"])
    if not backup.is_dir() or not _same_manifest(record["origin_manifest"], _tree_manifest(backup)):
        raise _error("backup-verification", "cutover backup is missing or changed")
    rolled_forward = output.parent / f".{output.name}.scope-extension-modified-{record['operation_id']}"
    if rolled_forward.exists():
        raise _error("rollback-conflict", f"rollback quarantine already exists: {rolled_forward}")
    restored_origin = False
    try:
        _release_audit_handles()
        output.rename(rolled_forward)
        if fault == "after-modified-rename":
            raise OSError("injected failure after modified rename")
        backup.rename(output)
        restored_origin = True
        if fault == "after-backup-restore":
            raise OSError("injected failure after backup restore")
        restored = _tree_manifest(output)
        if not _same_manifest(record["origin_manifest"], restored):
            raise _error("rollback-verification", "restored OUTPUT differs from the pre-cutover byte manifest")
        sqlite_checks = _sqlite_checks(output)
        if not sqlite_checks or not all(item["passed"] for item in sqlite_checks):
            raise _error("rollback-sqlite", f"restored SQLite verification failed: {sqlite_checks}")
        parent_operation_id = record.get("parent_operation_id")
        if parent_operation_id:
            parent_matches = [
                value
                for _path, value in _control_records(output)
                if value.get("operation_id") == parent_operation_id
            ]
            if len(parent_matches) != 1 or parent_matches[0].get("status") != "cutover-complete" or not _same_manifest(parent_matches[0].get("modified_manifest", {}), restored):
                raise _error("rollback-parent", "restored OUTPUT does not match the recorded parent cutover")
        record.update({
            "status": "rolled-back",
            "rolled_forward_output": str(rolled_forward),
            "restored_manifest": restored,
            "rollback_sqlite": sqlite_checks,
            "reactivated_operation_id": parent_operation_id,
        })
        json_write(control_path, record)
        selected_after = _control_selection(output, restored)["active"]
        actual_reactivated = selected_after[1]["operation_id"] if selected_after else None
        if actual_reactivated != parent_operation_id:
            raise _error("rollback-parent", f"active parent mismatch after rollback: expected {parent_operation_id}, got {actual_reactivated}")
        return {
            "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
            "status": "rolled-back",
            "operation_id": record["operation_id"],
            "reactivated_operation_id": parent_operation_id,
            "output": str(output),
            "modified_output": str(rolled_forward),
            "control": str(control_path),
            "sqlite": sqlite_checks,
        }
    except Exception as exc:
        try:
            if restored_origin and output.exists():
                output.rename(backup)
            if rolled_forward.exists() and not output.exists():
                rolled_forward.rename(output)
        finally:
            restored_modified = output.is_dir() and _same_manifest(record["modified_manifest"], _tree_manifest(output))
            record.update({
                "status": "cutover-complete" if restored_modified else "rollback-failed",
                "last_rollback_failure": str(exc),
                "modified_restored": restored_modified,
            })
            json_write(control_path, record)
        if isinstance(exc, CkbError):
            raise
        raise _error("rollback-failed", str(exc)) from exc

class _StartGate:
    def __init__(self) -> None:
        self.lock = threading.Lock()
        self.users = 0

def __init__(self) -> None:
        self.lock = threading.Lock()
        self.users = 0

def _release_start_gate(key: str, gate: _StartGate) -> None:
    with _START_GATES_GUARD:
        gate.users -= 1
        if gate.users == 0 and _START_GATES.get(key) is gate:
            _START_GATES.pop(key, None)

def default_session_stdio_root() -> Path:
    configured = os.environ.get("CKB_SESSION_STDIO_ROOT")
    return (Path(configured).expanduser() if configured else Path.home() / ".ckb" / "session-stdio").resolve()

def _path_identity(path: Path | str) -> str:
    value = str(Path(path).expanduser().resolve()).replace("\\", "/").rstrip("/")
    return value.casefold() if os.name == "nt" else value

def _digest(*values: object) -> str:
    text = "\0".join(str(value) for value in values)
    return hashlib.sha256(text.encode("utf-8", errors="strict")).hexdigest()

def session_digest(session_id: str) -> str:
    value = session_id.strip()
    if not value:
        raise CkbError("session stdio requires a non-empty session id")
    return _digest("session", value)

def _read_json(path: Path) -> dict[str, Any] | None:
    try:
        value = json_load(path)
        return value if isinstance(value, dict) else None
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        return None

def _validate_lifecycle_path_budget(directory: Path) -> dict[str, int]:
    characters = len(str(directory))
    if os.name == "nt" and characters > WINDOWS_LIFECYCLE_DIRECTORY_CHARS:
        raise CkbError(
            "session stdio lifecycle path budget exceeded: "
            f"directory_chars={characters}; directory_limit={WINDOWS_LIFECYCLE_DIRECTORY_CHARS}; "
            f"generated_path_limit={WINDOWS_MAX_PATH_CHARS}"
        )
    return {
        "directory_chars": characters,
        "directory_limit": WINDOWS_LIFECYCLE_DIRECTORY_CHARS,
        "generated_path_limit": WINDOWS_MAX_PATH_CHARS,
    }

def _write_lease(directory: Path, value: dict[str, Any], timeout: float = 3.0) -> None:
    """Replace lease state despite short Windows reader sharing conflicts."""

    path = _lease_path(directory)
    path.parent.mkdir(parents=True, exist_ok=True)
    _validate_lifecycle_path_budget(directory)
    temporary: Path | None = None
    for _attempt in range(32):
        candidate = directory / f".l{uuid.uuid4().hex[:6]}"
        try:
            with candidate.open("x", encoding="utf-8", newline="\n") as stream:
                stream.write(json.dumps(value, ensure_ascii=False, indent=2) + "\n")
            temporary = candidate
            break
        except FileExistsError:
            continue
    if temporary is None:
        raise CkbError("session stdio could not allocate a compact lease temporary file")
    deadline = time.monotonic() + timeout
    try:
        while True:
            try:
                os.replace(temporary, path)
                return
            except OSError as exc:
                sharing_conflict = os.name == "nt" and getattr(exc, "winerror", None) in {5, 32}
                if not sharing_conflict or time.monotonic() >= deadline:
                    raise
                time.sleep(POLL_SECONDS)
    finally:
        temporary.unlink(missing_ok=True)

def pid_exists(pid: int | None) -> bool:
    if not isinstance(pid, int) or pid <= 0:
        return False
    if pid == os.getpid():
        return True
    if os.name == "nt":
        try:
            import ctypes
            from ctypes import wintypes

            handle = ctypes.windll.kernel32.OpenProcess(0x00100000 | 0x1000, False, pid)
            if not handle:
                return False
            try:
                exit_code = wintypes.DWORD()
                if not ctypes.windll.kernel32.GetExitCodeProcess(handle, ctypes.byref(exit_code)):
                    return False
                return int(exit_code.value) == 259  # STILL_ACTIVE
            finally:
                ctypes.windll.kernel32.CloseHandle(handle)
        except Exception:
            return False
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except OSError:
        return False
    return True

def _force_terminate_pid(pid: int) -> bool:
    if not pid_exists(pid):
        return True
    if os.name == "nt":
        try:
            import ctypes

            process = ctypes.windll.kernel32.OpenProcess(0x0001 | 0x00100000, False, pid)
            if not process:
                return not pid_exists(pid)
            try:
                ctypes.windll.kernel32.TerminateProcess(process, 143)
                ctypes.windll.kernel32.WaitForSingleObject(process, 3000)
            finally:
                ctypes.windll.kernel32.CloseHandle(process)
            return not pid_exists(pid)
        except Exception:
            return False
    try:
        os.kill(pid, signal.SIGTERM)
    except ProcessLookupError:
        return True
    deadline = time.monotonic() + 2.0
    while pid_exists(pid) and time.monotonic() < deadline:
        time.sleep(POLL_SECONDS)
    if pid_exists(pid):
        try:
            os.kill(pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
    return not pid_exists(pid)

class _Reader(threading.Thread):
    def __init__(self, stream: TextIO, destination: queue.Queue[str] | list[str], name: str) -> None:
        super().__init__(name=name, daemon=False)
        self.stream = stream
        self.destination = destination

    def run(self) -> None:
        try:
            for line in self.stream:
                if isinstance(self.destination, queue.Queue):
                    self.destination.put(line)
                elif len(self.destination) < 200:
                    self.destination.append(line.rstrip("\r\n")[:2000])
        finally:
            if isinstance(self.destination, queue.Queue):
                self.destination.put("")

